NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'I Chronicles'

CHAPTERS = {
    1: {
        1: 'Aadam, Seet, Enos,',
        2: 'Keenan, Mahalalel, Jered,',
        3: 'Hanok, Metusalah, Lemek,',
        4: 'Nooa, Seem, Haam ja Jaafet.',
        5: 'Jaafetin pojat olivat Goomer, Maagog, Maadai, Jaavan, Tuubal, Mesek ja Tiiras.',
        6: 'Goomerin pojat olivat Askenas, Diifat ja Toogarma.',
        7: 'Jaavanin pojat olivat Elisa ja Tarsisa, kittiläiset ja roodanilaiset.',
        8: 'Haamin pojat olivat Kuus, Misraim, Puut ja Kanaan.',
        9: 'Kuusin pojat olivat Seba, Havila, Sabta, Raema ja Sabteka. Raeman pojat olivat Saba ja Dedan.',
        10: 'Kuusille syntyi Nimrod. Hän oli ensimmäinen valtias maan päällä.',
        11: 'Misraimille syntyivät luudilaiset, anamilaiset, lehabilaiset, naftuhilaiset,',
        12: 'patrokselaiset ja kasluhilaiset, joista filistealaiset ovat lähteneet, sekä kaftorilaiset.',
        13: 'Kanaanille syntyivät Siidon, hänen esikoisensa, ja Heet,',
        14: 'sekä jebusilaiset, amorilaiset, girgasilaiset,',
        15: 'hivviläiset, arkilaiset, siiniläiset,',
        16: 'arvadilaiset, semarilaiset ja hamatilaiset.',
        17: 'Seemin pojat olivat Eelam, Assur, Arpaksad, Luud, Aram, Uus, Huul, Geter ja Mesek.',
        18: 'Arpaksadille syntyi Selah, ja Selahille syntyi Eeber.',
        19: 'Eeberille syntyi kaksi poikaa. Toisen nimi oli Peleg, sillä hänen aikanaan jakaantui maa, ja hänen veljensä nimi oli Joktan.',
        20: 'Joktanille syntyivät Almodad, Selef, Hasarmavet, Jerah,',
        21: 'Hadoram, Uusal, Dikla,',
        22: 'Eebal, Abimael, Saba,',
        23: 'Oofir, Havila ja Joobab. Kaikki nämä olivat Joktanin poikia.',
        24: 'Seem, Arpaksad, Selah,',
        25: 'Eeber, Peleg, Regu,',
        26: 'Serug, Naahor, Terah,',
        27: 'Abram, se on Aabraham.',
        28: 'Aabrahamin pojat olivat Iisak ja Ismael.',
        29: 'Tämä on heidän sukuluettelonsa: Nebajot, Ismaelin esikoinen, Keedar, Adbeel, Mibsam,',
        30: 'Misma, Duuma, Massa, Hadad, Teema,',
        31: 'Jetur, Naafis ja Keedma. Nämä olivat Ismaelin pojat.',
        32: 'Keturan, Aabrahamin sivuvaimon, pojat, jotka tämä synnytti, olivat Simran, Joksan, Medan, Midian, Jisbak ja Suuah. Joksanin pojat olivat Saba ja Dedan.',
        33: 'Midianin pojat olivat Eefa, Eefer, Hanok, Abida ja Eldaa. Kaikki nämä olivat Keturan jälkeläisiä.',
        34: 'Aabrahamille syntyi Iisak. Iisakin pojat olivat Eesau ja Israel.',
        35: 'Eesaun pojat olivat Elifas, Reguel, Jeus, Jaelam ja Koorah.',
        36: 'Elifaan pojat olivat Teeman, Oomar, Sefi, Gaetam, Kenas, Timna ja Amalek.',
        37: 'Reguelin pojat olivat Nahat, Sera, Samma ja Missa.',
        38: 'Seirin pojat olivat Lootan, Soobal, Sibon, Ana, Diison, Eeser ja Diisan.',
        39: 'Lootanin pojat olivat Hoori ja Hoomam, ja Lootanin sisar oli Timna.',
        40: 'Soobalin pojat olivat Aljan, Maanahat, Eebal, Sefi ja Oonan. Sibonin pojat olivat Aija ja Ana.',
        41: 'Anan pojat olivat Diison sekä Diisonin pojat Hamran, Esban, Jitran ja Keran.',
        42: 'Eeserin pojat olivat Bilhan, Saavan ja Jaakan. Diisanin pojat olivat Uus ja Aran.',
        43: 'Nämä olivat ne kuninkaat, jotka hallitsivat Edomin maassa, ennen kuin mikään kuningas oli hallinnut israelilaisia: Bela, Beorin poika, ja hänen kaupunkinsa nimi oli Dinhaba.',
        44: 'Kun Bela kuoli, tuli Joobab, Seran poika, Bosrasta, kuninkaaksi hänen jälkeensä.',
        45: 'Kun Joobab kuoli, tuli Huusam, teemanilaisten maasta, kuninkaaksi hänen jälkeensä.',
        46: 'Kun Huusam kuoli, tuli Hadad, Bedadin poika, kuninkaaksi hänen jälkeensä, hän, joka voitti midianilaiset Mooabin maassa. Hänen kaupunkinsa nimi oli Avit.',
        47: 'Kun Hadad kuoli, tuli Samla, Masrekasta, kuninkaaksi hänen jälkeensä.',
        48: 'Kun Samla kuoli, tuli Saul, virran rannalla olevasta Rehobotista, kuninkaaksi hänen jälkeensä.',
        49: 'Kun Saul kuoli, tuli Baal-Haanan, Akborin poika, kuninkaaksi hänen jälkeensä.',
        50: 'Kun Baal-Haanan kuoli, tuli Hadad kuninkaaksi hänen jälkeensä, ja hänen kaupunkinsa nimi oli Paagi, ja hänen vaimonsa nimi oli Mehetabel, Matredin tytär, joka oli Mee-Saahabin tytär.',
        51: 'Hadad kuoli. Edomin sukuruhtinaat olivat: ruhtinas Timna, ruhtinas Alva, ruhtinas Jetet,',
        52: 'ruhtinas Oholibama, ruhtinas Eela, ruhtinas Piinon,',
        53: 'ruhtinas Kenas, ruhtinas Teeman, ruhtinas Mibsar,',
        54: 'ruhtinas Magdiel, ruhtinas Iiram. Nämä olivat Edomin sukuruhtinaat.',
    },
    2: {
        1: 'Nämä olivat Israelin pojat: Ruuben, Simeon, Leevi ja Juuda, Isaskar ja Sebulon,',
        2: 'Daan, Joosef ja Benjamin, Naftali, Gaad ja Asser.',
        3: 'Juudan pojat olivat Eer, Oonan ja Seela. Nämä kolme synnytti hänelle Suuahin tytär, kanaanilainen. Eer, Juudan esikoinen, ei ollut otollinen Herran silmissä. Sen tähden hän antoi hänen kuolla.',
        4: 'Taamar, Juudan miniä, synnytti hänelle Pereksen ja Seran. Juudan poikia oli kaikkiaan viisi.',
        5: 'Pereksen pojat olivat Hesron ja Haamul.',
        6: 'Seran pojat olivat Simri, Eetan, Heeman, Kalkol ja Daara. Heitä oli kaikkiaan viisi.',
        7: 'Karmin pojat olivat Aakar, joka syöksi Israelin onnettomuuteen, kun oli uskoton ja anasti tuhon omaksi vihittyä.',
        8: 'Eetanin poika oli Asarja.',
        9: 'Hesronin pojat, jotka hänelle syntyivät, olivat Jerahmeel, Raam ja Kelubai.',
        10: 'Raamille syntyi Amminadab, ja Amminadabille syntyi Nahson, Juudan jälkeläisten ruhtinas.',
        11: 'Nahsonille syntyi Salma, ja Salmalle syntyi Booas.',
        12: 'Booaalle syntyi Oobed, ja Oobedille syntyi Iisai.',
        13: 'Iisaille syntyi esikoisena Eliab, toisena Abinadab, kolmantena Simea,',
        14: 'neljäntenä Netanel, viidentenä Raddai,',
        15: 'kuudentena Oosem ja seitsemäntenä Daavid.',
        16: 'Heidän sisarensa olivat Seruja ja Abigail. Serujan pojat olivat Abisai, Jooab ja Asael, kaikkiaan kolme.',
        17: 'Abigail synnytti Amasan, ja Amasan isä oli ismaelilainen Jeter.',
        18: 'Kaalebille, Hesronin pojalle, syntyi lapsia Asubasta, hänen vaimostaan, ja Jeriotista. Nämä olivat Asuban pojat: Jeeser, Soobab ja Ardon.',
        19: 'Kun Asuba kuoli, Kaaleb nai Efratin, ja tämä synnytti hänelle Huurin.',
        20: 'Huurille syntyi Uuri, ja Uurille syntyi Besalel.',
        21: 'Sen jälkeen Hesron meni Maakirin, Gileadin isän, tyttären luo ja nai tämän ollessaan kuudenkymmenen vuoden vanha. Tämä synnytti hänelle Segubin.',
        22: 'Segubille syntyi Jaair. Tällä oli kaksikymmentä kolme kaupunkia Gileadin maassa.',
        23: 'Gesurilaiset ja aramilaiset ottivat heiltä Jaairin leirikylät ja Kenatin sekä sen tytärkaupungit, kuusikymmentä kaupunkia. Kaikki nämä olivat Maakirin, Gileadin isän, poikia.',
        24: 'Kun Hesron oli kuollut Kaaleb-Efratassa, synnytti Abia – hän oli Hesronin vaimo – hänelle Ashurin, Tekoan isän.',
        25: 'Jerahmeelin, Hesronin esikoisen, pojat olivat Raam, esikoinen, ja Buuna, Ooren, Oosem ja Ahia.',
        26: 'Jerahmeelilla oli vielä toinen vaimo, jonka nimi oli Atara. Hän oli Oonamin äiti.',
        27: 'Raamin, Jerahmeelin esikoisen, pojat olivat Maas, Jaamin ja Eeker.',
        28: 'Oonamin pojat olivat Sammai ja Jaada. Sammain pojat olivat Naadab ja Abisur.',
        29: 'Abisurin vaimon nimi oli Abihail, ja tämä synnytti hänelle Ahbanin ja Moolidin.',
        30: 'Naadabin pojat olivat Seled ja Appaim. Seled kuoli lapsettomana.',
        31: 'Appaimin poika oli Jisi, ja Jisin poika oli Seesan. Seesanin poika oli Ahlai.',
        32: 'Jaadan, Sammain veljen, pojat olivat Jeter ja Joonatan. Jeter kuoli lapsettomana.',
        33: 'Joonatanin pojat olivat Pelet ja Saasa. Nämä olivat Jerahmeelin jälkeläisiä.',
        34: 'Mutta Seesanilla ei ollut poikia, vaan ainoastaan tyttäriä. Seesanilla oli egyptiläinen palvelija, jonka nimi oli Jarha.',
        35: 'Seesan antoi tyttärensä vaimoksi palvelijalleen Jarhalle, ja hän synnytti tälle Attain.',
        36: 'Attaille syntyi Naatan, ja Naatanille syntyi Saabad.',
        37: 'Saabadille syntyi Eflal, ja Eflalille syntyi Oobed.',
        38: 'Oobedille syntyi Jeehu, ja Jeehulle syntyi Asarja.',
        39: 'Asarjalle syntyi Heles, ja Helekselle syntyi Eleasa.',
        40: 'Eleasalle syntyi Sismai, ja Sismaille syntyi Sallum.',
        41: 'Sallumille syntyi Jekamja, ja Jekamjalle syntyi Elisama.',
        42: 'Kaalebin, Jerahmeelin veljen, pojat olivat Meesa, hänen esikoisensa, joka oli Siifin isä, ja Maaresan, Hebronin isän, pojat.',
        43: 'Hebronin pojat olivat Koorah, Tappuuah, Rekem ja Sema.',
        44: 'Semalle syntyi Raham, Jorkeamin isä, ja Rekemille syntyi Sammai.',
        45: 'Sammain poika oli Maaon, ja Maaon oli Beet-Suurin isä.',
        46: 'Eefa, Kaalebin sivuvaimo, synnytti Haaranin, Moosan ja Gaaseksen. Haaranille syntyi Gaases.',
        47: 'Jahdain pojat olivat Regem, Jootam, Geesan, Pelet, Eefa ja Saaf.',
        48: 'Maaka, Kaalebin sivuvaimo, synnytti Seberin ja Tirhanan.',
        49: 'Hän synnytti myös Saafin, Madmannan isän, Sevan, Makbenan isän ja Gibean isän. Kaalebin tytär oli Aksa.',
        50: 'Nämä olivat Kaalebin jälkeläisiä. Huurin, Efratan esikoisen, pojat olivat Soobal, Kirjat-Jearimin isä,',
        51: 'Salma, Beetlehemin isä, ja Haaref, Beet-Gaaderin isä.',
        52: 'Soobalin, Kirjat-Jearimin isän, jälkeläiset olivat Rooe ja toinen puoli Menuhotia.',
        53: 'Kirjat-Jearimin suvut olivat jeteriläiset, puutilaiset, suumatilaiset ja misrailaiset. Heistä ovat soratilaiset ja estaolilaiset lähteneet.',
        54: 'Salman jälkeläiset olivat Beetlehem ja netofalaiset, Atrot, Beet-Jooab ja toinen puoli manahtilaisia, sorilaiset.',
        55: 'Kirjanoppineiden suvut, jotka asuivat Jaebeksessa, olivat tiratilaiset, simatilaiset ja sukatilaiset. Nämä olivat ne keeniläiset, jotka polveutuvat Hammatista, Reekabin suvun isästä.',
    },
    3: {
        1: 'Nämä ovat ne Daavidin pojat, jotka syntyivät hänelle Hebronissa: esikoinen Amnon, jisreeliläisestä Ahinoamista; toinen Daniel, karmelilaisesta Abigailista;',
        2: 'kolmas Absalom, Maakan, Gesurin kuninkaan Talmain tyttären, poika; neljäs Adonia, Haggitin poika;',
        3: 'viides Sefatja, Abitalista; kuudes Jitream, hänen vaimostaan Eglasta.',
        4: 'Nämä kuusi syntyivät hänelle Hebronissa, jossa hän hallitsi seitsemän vuotta ja kuusi kuukautta. Mutta Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.',
        5: 'Nämä syntyivät hänelle Jerusalemissa: Simea, Soobab, Naatan ja Salomo, kaikkiaan neljä, Batsuuasta, Ammielin tyttärestä;',
        6: 'sitten Jibhar, Elisama, Elifelet,',
        7: 'Noogah, Nefeg, Jaafia,',
        8: 'Elisama, Eljada ja Elifelet; kaikkiaan yhdeksän.',
        9: 'Tässä ovat kaikki Daavidin pojat, lukuun ottamatta sivuvaimojen poikia. Taamar oli heidän sisarensa.',
        10: 'Salomon poika oli Rehabeam; tämän poika Abia; tämän poika Aasa; tämän poika Joosafat;',
        11: 'tämän poika Jooram; tämän poika Ahasja; tämän poika Jooas;',
        12: 'tämän poika Amasja; tämän poika Asarja; tämän poika Jootam;',
        13: 'tämän poika Aahas; tämän poika Hiskia; tämän poika Manasse;',
        14: 'tämän poika Aamon; tämän poika Joosia.',
        15: 'Joosian pojat olivat esikoinen Joohanan, toinen Joojakim, kolmas Sidkia, neljäs Sallum.',
        16: 'Joojakimin pojat olivat hänen poikansa Jekonja ja tämän poika Sidkia.',
        17: 'Vangitun Jekonjan pojat olivat: hänen poikansa Sealtiel,',
        18: 'Malkiram, Pedaja, Senassar, Jekamja, Hoosama ja Nebadja.',
        19: 'Pedajan pojat olivat Serubbaabel ja Siimei. Serubbaabelin pojat olivat Mesullam ja Hananja, ja heidän sisarensa oli Selomit;',
        20: 'vielä Hasuba, Oohel, Berekja, Hasadja ja Juusab-Hesed, kaikkiaan viisi.',
        21: 'Hananjan pojat olivat Pelatja ja Jesaja, Refajan pojat, Arnanin pojat, Obadjan pojat ja Sekanjan pojat.',
        22: 'Sekanjan poika oli Semaja. Semajan pojat olivat Hattus, Jigal, Baariah, Nearja ja Saafat, kaikkiaan kuusi.',
        23: 'Nearjan pojat olivat Eljoenai, Hiskia, Asrikam, kaikkiaan kolme.',
        24: 'Eljoenain pojat olivat Hoodavja, Eljasib, Pelaja, Akkub, Joohanan, Delaja ja Anani, kaikkiaan seitsemän.',
    },
    4: {
        1: 'Juudan pojat olivat Peres, Hesron, Karmi, Huur ja Soobal.',
        2: 'Reajalle, Soobalin pojalle, syntyi Jahat, ja Jahatille syntyivät Ahumai ja Lahad. Nämä ovat soratilaisten suvut.',
        3: 'Nämä olivat Eetamin isän pojat: Jisreel, Jisma ja Jidbas, ja heidän sisarensa nimi oli Haslelponi;',
        4: 'vielä Penuel, Gedorin isä, ja Eeser, Huusan isä. Nämä olivat Huurin, Efratan esikoisen, Beetlehemin isän, pojat.',
        5: 'Ashurilla, Tekoan isällä, oli kaksi vaimoa, Hela ja Naara.',
        6: 'Naara synnytti hänelle Ahussamin, Heeferin, Teemenin ja ahastarilaiset. Nämä olivat Naaran pojat.',
        7: 'Helan pojat olivat Seret, Soohar ja Etnan.',
        8: 'Koosille syntyivät Aanub ja Soobeba sekä Aharhelin, Haarumin pojan, suvut.',
        9: 'Jabes oli suuremmassa arvossa pidetty kuin hänen veljensä. Hänen äitinsä oli antanut hänelle nimen Jabes sanoen: "Olen synnyttänyt hänet kipuja kärsien."',
        10: 'Jabes huusi Israelin Jumalaa, sanoen: "Jospa siunaisit minua ja laajentaisit alueeni. Jospa kätesi olisi kanssani ja varjelisit pahasta, että pääsisin kipuja kärsimästä!" Jumala antoi hänen pyyntönsä toteutua.',
        11: 'Kelubille, Suuhan veljelle, syntyi Mehir. Hän oli Estonin isä.',
        12: 'Estonille syntyivät Beet-Raafa, Paaseah ja Tehinna, Naahaan kaupungin isä. Nämä olivat Reekan miehet.',
        13: 'Kenaan pojat olivat Otniel ja Seraja. Otnielin pojat olivat: Hatat.',
        14: 'Meonotaille syntyi Ofra. Serajalle syntyi Jooab, Seppienlaakson isä. Sillä he olivat seppiä.',
        15: 'Kaalebin, Jefunnen pojan, pojat olivat Iiru, Eela ja Naam sekä Eelan pojat ja Kenas.',
        16: 'Jehallelelin pojat olivat Siif, Siifa, Tiireja ja Asarel.',
        17: 'Esran pojat olivat Jeter, Mered, Eefer ja Jaalon. Vaimo tuli raskaaksi ja synnytti Mirjamin, Sammain ja Jisbahin, Estemoan isän.',
        18: 'Hänen juudansukuinen vaimonsa synnytti Jeredin, Gedorin isän, Heberin, Sookon isän, ja Jekutielin, Saanoahin isän. Nämä olivat Bitjan, faraon tyttären, poikia, jonka Mered oli ottanut vaimokseen.',
        19: 'Hoodian vaimon, Nahamin sisaren, pojat olivat Kegilan isä, garmilainen, ja maakatilainen Estemoa.',
        20: 'Siimonin pojat olivat Amnon ja Rinna, Ben-Haanan ja Tiilon. Jisin pojat olivat Soohet ja Soohetin poika.',
        21: 'Seelan, Juudan pojan, pojat olivat Eer, Leekan isä, Lada, Maaresan isä, ja pellavakankaiden kutojien suvut Beet-Asbeasta;',
        22: 'Jookim ja Kooseban miehet sekä Jooas ja Saaraf, jotka hallitsivat Mooabia, ja Jaasubi-Lehem. Mutta nämä ovat vanhoja asioita.',
        23: 'He olivat niitä savenvalajia, jotka asuvat Netaimissa ja Gederassa. He asuivat siellä kuninkaan luona ja olivat hänen työssään.',
        24: 'Simeonin pojat olivat Nemuel ja Jaamin, Jaarib, Sera ja Saul.',
        25: 'Tämän poika oli Sallum, tämän poika Mibsam, tämän poika Misma.',
        26: 'Misman pojat olivat: hänen poikansa Hammuel, tämän poika Sakkur ja tämän poika Siimei.',
        27: 'Siimeillä oli kuusitoista poikaa ja kuusi tytärtä, mutta hänen veljillään ei ollut monta lasta, eikä koko heidän sukunsa lisääntynyt Juudan lasten määrään.',
        28: 'He asuivat Beersebassa, Mooladassa ja Hasar-Suualissa,',
        29: 'Bilhassa, Esemissä ja Tooladissa,',
        30: 'Betuelissa, Hormassa ja Siklagissa,',
        31: 'Beet-Markabotissa, Hasar-Suusimissa, Beet-Birissä ja Saaraimissa. Nämä olivat heidän kaupunkinsa Daavidin hallitukseen asti.',
        32: 'Heidän kylänsä olivat Eetam, Ain, Rimmon, Tooken ja Aasan – viisi kaupunkia.',
        33: 'Siihen tulivat lisäksi kaikki ne heidän kylänsä, jotka olivat näiden kaupunkien ympärillä, aina Baaliin asti. Nämä olivat heidän asuinpaikkansa ja heillä oli omat sukuluettelonsa.',
        34: 'Vielä: Mesobab, Jamlek, Joosa, Amasjan poika,',
        35: 'Jooel, Jeehu, Joosibjan poika, joka oli Serajan poika, joka Asielin poika;',
        36: 'Eljoenai, Jaakoba, Jesohaja, Asaja, Adiel, Jesimiel, Benaja',
        37: 'ja Siisa, Sifin poika, joka oli Allonin poika, joka Jedajan poika, joka Simrin poika, joka Semajan poika.',
        38: 'Nämä nimeltä mainitut olivat sukujensa ruhtinaita, ja heidän perhekuntansa olivat levinneet ja lisääntyneet.',
        39: 'He kulkivat Gedoriin päin, aina laakson itäiseen osaan saakka hakeakseen laidunta lampailleen.',
        40: 'He löysivät lihavan ja hyvän laitumen, ja maa oli tilava joka suuntaan sekä rauhallinen ja levollinen, sillä ne, jotka olivat asuneet siellä ennen, olivat haamilaisia.',
        41: 'Mutta nämä nimeltä luetellut tulivat Hiskian, Juudan kuninkaan, päivinä ja valtasivat heidän telttansa ja voittivat meunilaiset, jotka olivat siellä, ja vihkivät heidät tuhon omiksi, aina tähän päivään asti, ja asettuivat heidän sijaansa, sillä siellä oli laidunta heidän lampailleen.',
        42: 'Heistä, simeonilaisista, meni viisisataa miestä Seirin vuoristoon, ja heidän etunenässään olivat Pelatja, Nearja, Refaja ja Ussiel, Jisin pojat.',
        43: 'He surmasivat ne, jotka olivat jäljellä pelastuneista amalekilaisista, ja jäivät sinne asumaan aina tähän päivään asti.',
    },
    5: {
        1: 'Ruubenin, Israelin esikoisen, pojat olivat – hän oli näet esikoinen, mutta koska hän saastutti isänsä vuoteen, annettiin hänen esikoisuutensa Joosefin, Israelin pojan, pojille, kuitenkin niin, ettei heitä merkitty sukuluetteloon esikoisina,',
        2: 'sillä Juuda tuli voimallisimmaksi veljiensä joukossa, ja yhdestä hänen jälkeläisistään tuli ruhtinas, mutta esikoisuus joutui Joosefille –',
        3: 'Ruubenin, Israelin esikoisen, pojat olivat Hanok ja Pallu, Hesron ja Karmi.',
        4: 'Jooelin pojat olivat: hänen poikansa Semaja, tämän poika Goog, tämän poika Siimei,',
        5: 'tämän poika Miika, tämän poika Reaja, tämän poika Baal',
        6: 'ja tämän poika Beera, jonka Assurin kuningas Tillegat-Pilneser vei karkotukseen. Hän oli ruubenilaisten ruhtinas.',
        7: 'Hänen veljensä olivat sukujensa mukaan, kun heidät merkittiin sukuluetteloon heidän polveutumisensa mukaan: Jegiel, päämies, Sakarja,',
        8: 'Bela, Aasaan poika, joka oli Seman poika, joka Jooelin poika. Hän asui Aroerissa ja aina Neboon ja Baal-Meoniin asti.',
        9: 'Idässä hän asui erämaahan saakka, joka alkaa Eufrat-virrasta, sillä heillä oli suuria karjalaumoja Gileadin maassa.',
        10: 'Mutta Saulin päivinä he kävivät sotaa hagrilaisia vastaan, ja kun nämä olivat joutuneet heidän käsiinsä, he asettuivat heidän telttoihinsa Gileadin koko itäistä rajaseutua myöten.',
        11: 'Gaadilaiset asuivat heidän kanssaan rajanaapureina Baasanin maassa Salkaan saakka:',
        12: 'Jooel päämiehenä ja Saafam toisena, sitten Janai ja Saafat Baasanissa.',
        13: 'Heidän veljensä olivat, perhekuntiensa mukaan: Miikael, Mesullam, Seba, Joorai, Jakan, Siia ja Eeber, kaikkiaan seitsemän.',
        14: 'Nämä olivat Abihailin pojat, joka oli Huurin poika, joka Jaaroahin poika, joka Gileadin poika, joka Miikaelin poika, joka Jesisain poika, joka Jahdon poika, joka Buusin poika.',
        15: 'Ahi, Abdielin poika, joka oli Guunin poika, oli heidän perhekuntiensa päämies.',
        16: 'He asuivat Gileadissa, Baasanissa ja sen tytärkaupungeissa sekä kaikilla Saaronin laidunmailla, niin kauas kuin ne ulottuivat.',
        17: 'Kaikki nämä merkittiin sukuluetteloon Juudan kuninkaan Jootamin ja Israelin kuninkaan Jerobeamin päivinä.',
        18: 'Ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa – sotakuntoisia miehiä, jotka kantoivat kilpeä ja miekkaa ja jännittivät jousta ja olivat taisteluun harjaantuneita, neljäkymmentäneljä tuhatta seitsemänsataa kuusikymmentä sotakelpoista miestä –',
        19: 'kävivät sotaa hagrilaisia, Jeturia, Naafista ja Noodabia vastaan.',
        20: 'He saivat apua näitä vastaan, niin että hagrilaiset ja kaikki, jotka olivat heidän kanssaan, joutuivat heidän käsiinsä. Sillä he huusivat taistelussa Jumalan puoleen, ja hän kuuli heidän rukouksensa, koska he turvasivat häneen.',
        21: 'He veivät saaliinaan heidän karjansa, viisikymmentä tuhatta kamelia, kaksisataa viisikymmentä tuhatta lammasta ja kaksituhatta aasia, sekä satatuhatta ihmistä.',
        22: 'Paljon oli surmattuina kaatuneita, sillä sota oli Jumalan sota. He asettuivat asumaan heidän sijaansa aina karkotukseen asti.',
        23: 'Toinen puoli Manassen sukukuntaa asui siinä maassa, Baasanista aina Baal-Hermoniin ja Seniriin ja Hermon-vuoreen saakka. Heitä oli paljon.',
        24: 'Nämä olivat heidän perhekuntiensa päämiehet: Eefer, Jisi, Eliel, Asriel, Jeremia, Hoodavja ja Jahdiel, väkeviä sankareita, nimekkäitä miehiä, perhekuntiensa päämiehiä.',
        25: 'Mutta he tulivat uskottomiksi isiensä Jumalaa kohtaan ja juoksivat haureudessa maan kansojen jumalien perässä, niiden kansojen, jotka Jumala oli hävittänyt heidän edeltään.',
        26: 'Niin Israelin Jumala herätti Puulin, Assurin kuninkaan, hengen ja Tillegat-Pilneserin, Assurin kuninkaan, hengen ja kuljetutti heidät, ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa, karkotukseen ja antoi viedä heidät Halahiin, Haaboriin, Haaraan ja Goosanin joen rannoille, missä he tänäkin päivänä ovat.',
        27: 'Leevin pojat olivat Geerson, Kehat ja Merari.',
        28: 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.',
        29: 'Amramin lapset olivat Aaron, Mooses ja Mirjam. Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.',
        30: 'Eleasarille syntyi Piinehas, Piinehaalle syntyi Abisua.',
        31: 'Abisualle syntyi Bukki, ja Bukille syntyi Ussi.',
        32: 'Ussille syntyi Serahja, ja Serahjalle syntyi Merajot.',
        33: 'Merajotille syntyi Amarja, ja Amarjalle syntyi Ahitub.',
        34: 'Ahitubille syntyi Saadok, ja Saadokille syntyi Ahimaas.',
        35: 'Ahimaasille syntyi Asarja, ja Asarjalle syntyi Joohanan.',
        36: 'Joohananille syntyi Asarja, hän joka toimitti papinvirkaa temppelissä, jonka Salomo rakennutti Jerusalemiin.',
        37: 'Asarjalle syntyi Amarja, ja Amarjalle syntyi Ahitub.',
        38: 'Ahitubille syntyi Saadok, ja Saadokille syntyi Sallum.',
        39: 'Sallumille syntyi Hilkia, ja Hilkialle syntyi Asarja.',
        40: 'Asarjalle syntyi Seraja, ja Serajalle syntyi Jehosadak.',
        41: 'Mutta Jehosadakin oli lähdettävä mukaan silloin, kun Herra antoi Nebukadnessarin viedä Juudan ja Jerusalemin karkotukseen.',
    },
    6: {
        1: 'Leevin pojat olivat Geersom, Kehat ja Merari.',
        2: 'Nämä ovat Geersomin poikien nimet: Libni ja Siimei.',
        3: 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.',
        4: 'Merarin pojat olivat Mahli ja Muusi. Nämä olivat leeviläisten suvut heidän isiensä mukaan.',
        5: 'Geersomista polveutuivat hänen poikansa Libni, tämän poika Jahat, tämän poika Simma,',
        6: 'tämän poika Jooah, tämän poika Iddo, tämän Sera ja tämän poika Jeatrai.',
        7: 'Kehatin pojat olivat: hänen poikansa Amminadab, tämän poika Koorah, tämän poika Assir,',
        8: 'tämän poika Elkana, tämän poika Ebjasaf, tämän poika Assir,',
        9: 'tämän poika Tahat, tämän poika Uuriel, tämän poika Ussia ja tämän poika Saul.',
        10: 'Elkanan pojat olivat Amasai ja Ahimot.',
        11: 'Elkana: Elkanan pojat, Suufai, tämän poika Nahat,',
        12: 'tämän poika Eliab, tämän poika Jeroham, tämän poika Elkana.',
        13: 'Samuelin pojat olivat esikoinen Vasni ja Abia.',
        14: 'Merarin pojat olivat: Mahli, tämän poika Libni, tämän poika Siimei, tämän poika Ussa,',
        15: 'tämän poika Simea, tämän poika Haggia ja tämän poika Asaja.',
        16: 'Nämä ovat ne, jotka Daavid asetti pitämään huolta laulusta Herran temppelissä, sen jälkeen kun arkki oli saanut leposijan.',
        17: 'He palvelivat veisaajina ilmestysmajan asumuksen edessä, kunnes Salomo rakensi Herran temppelin Jerusalemiin. He toimittivat virkaansa, kuten heille oli säädetty.',
        18: 'Nämä ovat ne, jotka palvelivat, ja nämä heidän poikansa: Kehatilaisia: Heeman, veisaaja, Jooelin poika, joka oli Samuelin poika,',
        19: 'joka Elkanan poika, joka Jerohamin poika, joka Elielin poika, joka Tooahin poika,',
        20: 'joka Suufin poika, joka Elkanan poika, joka Mahatin poika, joka Amasain poika,',
        21: 'joka Elkanan poika, joka Jooelin poika, joka Asarjan poika, joka Sefanjan poika,',
        22: 'joka Tahatin poika, joka Assirin poika, joka Ebjasafin poika, joka Koorahin poika,',
        23: 'joka Jisharin poika, joka Kehatin poika, joka Leevin poika, joka Israelin poika.',
        24: 'Ja hänen veljensä Aasaf, joka seisoi hänen oikealla puolellaan, Aasaf, Berekjan poika, joka oli Simean poika,',
        25: 'joka Miikaelin poika, joka Baasejan poika, joka Malkian poika,',
        26: 'joka Etnin poika, joka Seran poika, joka Adajan poika,',
        27: 'joka Eetanin poika, joka Simman poika, joka Siimein poika,',
        28: 'joka Jahatin poika, joka Geersomin poika, joka Leevin poika.',
        29: 'Heidän veljensä, Merarin pojat, vasemmalla puolella: Eetan, Kiisin poika, joka oli Abdin poika, joka Mallukin poika,',
        30: 'joka Hasabjan poika, joka Amasjan poika, joka Hilkian poika,',
        31: 'joka Amsin poika, joka Baanin poika, joka Semerin poika,',
        32: 'joka Mahlin poika, joka Muusin poika, joka Merarin poika, joka Leevin poika.',
        33: 'Heidän veljensä, leeviläiset, olivat annetut toimittamaan kaikkinaista palvelusta Jumalan temppeliasumuksessa.',
        34: 'Mutta Aaron ja hänen poikansa polttivat uhreja polttouhrialttarilla ja suitsutusalttarilla, toimittivat kaikki tehtävät kaikkeinpyhimmässä ja Israelin sovituksen, aivan niin kuin Jumalan palvelija Mooses oli käskenyt.',
        35: 'Nämä olivat Aaronin pojat: hänen poikansa Eleasar, tämän poika Piinehas, tämän poika Abisua,',
        36: 'tämän poika Bukki, tämän poika Ussi, tämän poika Serahja,',
        37: 'tämän poika Merajot, tämän poika Amarja, tämän poika Ahitub,',
        38: 'tämän poika Saadok, tämän poika Ahimaas.',
        39: 'Nämä olivat heidän asuinpaikkansa, heidän leiripaikkojensa mukaan, heidän alueellaan: Niille Aaronin jälkeläisille, jotka olivat kehatilaisten sukua, sillä he saivat arpaosan,',
        40: 'annettiin Hebron Juudan maasta, ympärillä olevine laidunmaineen.',
        41: 'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle.',
        42: 'Aaronin jälkeläisille annettiin turvakaupungit Hebron, Libna laidunmaineen, Jattir, Estemoa laidunmaineen,',
        43: 'Hiilen laidunmaineen, Debir laidunmaineen,',
        44: 'Aasan laidunmaineen ja Beet-Semes laidunmaineen.',
        45: 'Benjaminin sukukunnasta Geba laidunmaineen, Aalemet laidunmaineen ja Anatot laidunmaineen. Heidän kaupunkejaan oli kaikkiaan kolmetoista kaupunkia, heidän sukujensa mukaan.',
        46: 'Muut kehatilaiset saivat arvalla sukujensa mukaan Efraimin sukukunnalta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.',
        47: 'Geersomilaiset saivat sukujensa mukaan Isaskarin sukukunnalta, Asserin sukukunnalta, Naftalin sukukunnalta ja Manassen sukukunnalta Baasanista kolmetoista kaupunkia.',
        48: 'Merarilaiset saivat arvalla sukujensa mukaan Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.',
        49: 'Israelilaiset antoivat leeviläisille nämä kaupungit laidunmaineen.',
        50: 'He antoivat arvalla Juudan lasten sukukunnasta, simeonilaisten sukukunnasta ja benjaminilaisten sukukunnasta nämä nimeltä mainitut kaupungit.',
        51: 'Kehatilaisten suvuista muutamat saivat arvalla Efraimin sukukunnalta alueekseen seuraavat kaupungit:',
        52: 'heille annettiin turvakaupungit Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,',
        53: 'Jokmeam laidunmaineen, Beet-Hooron laidunmaineen,',
        54: 'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen.',
        55: 'Toisesta puolesta Manassen sukukuntaa Aaner laidunmaineen ja Bileam laidunmaineen. Nämä tulivat muitten kehatilaisten suvuille.',
        56: 'Geersomilaiset saivat sukujensa mukaan toiselta puolelta Manassen sukukuntaa Goolanin laidunmaineen Baasanista ja Astarotin laidunmaineen;',
        57: 'ja Isaskarin sukukunnalta Kedeksen laidunmaineen, Dobratin laidunmaineen,',
        58: 'Raamotin laidunmaineen ja Aanemin laidunmaineen;',
        59: 'ja Asserin sukukunnalta Maasalin laidunmaineen, Abdonin laidunmaineen,',
        60: 'Huukokin laidunmaineen ja Rehobin laidunmaineen;',
        61: 'ja Naftalin sukukunnalta Kedeksen laidunmaineen Galileasta, Hammonin laidunmaineen ja Kirjataimin laidunmaineen.',
        62: 'Muut merarilaiset saivat Sebulonin sukukunnalta Rimmonin laidunmaineen ja Taaborin laidunmaineen;',
        63: 'ja tuolta puolelta Jerikon Jordanin, Jordanista auringonnousuun päin, Ruubenin sukukunnalta Beserin laidunmaineen erämaasta, Jahaan laidunmaineen,',
        64: 'Kedemotin laidunmaineen, Meefatin laidunmaineen;',
        65: 'ja Gaadin sukukunnalta Raamotin laidunmaineen Gileadista, Mahanaimin laidunmaineen,',
        66: 'Hesbonin laidunmaineen ja Jaeserin laidunmaineen.',
    },
    7: {
        1: 'Isaskarin pojat olivat Toola, Puua, Jaasub ja Simron, kaikkiaan neljä.',
        2: 'Toolan pojat olivat Ussi, Refaja, Jeriel, Jahmai, Jibsam ja Samuel, jotka olivat perhekuntiensa päämiehiä, Toolan jälkeläisiä, väkeviä sankareita, polveutumisensa mukaan. Daavidin aikana oli heidän lukumääränsä kaksikymmentäkaksi tuhatta kuusisataa.',
        3: 'Ussin poika oli Jisrahja, ja Jisrahjan pojat olivat Miikael, Obadja, Jooel ja Jissia, kaikkiaan viisi, kaikki päämiehiä.',
        4: 'Heitä seurasi polveutumisensa ja perhekuntiensa mukaan taisteluun valmiina sotajoukkoina kolmekymmentäkuusi tuhatta miestä, sillä heillä oli paljon vaimoja ja lapsia.',
        5: 'Heidän veljensä, kaikissa Isaskarin suvuissa, olivat väkeviä sankareita. Sukuluetteloihin heitä oli merkitty kaikkiaan kahdeksankymmentäseitsemän tuhatta.',
        6: 'Benjaminin [poikia olivat]: Bela, Beker ja Jediael, kaikkiaan kolme.',
        7: 'Belan pojat olivat Esbon, Ussi, Ussiel, Jerimot ja Iiri, kaikkiaan viisi, perhekuntapäämiehiä, väkeviä sankareita. Sukuluetteloihin heitä oli merkitty kaksikymmentäkaksi tuhatta kolmekymmentä neljä.',
        8: 'Bekerin pojat olivat Semira, Jooas, Elieser, Eljoenai, Omri, Jeremot, Abia, Anatot ja Aalemet; kaikki nämä olivat Bekerin poikia.',
        9: 'Heitä oli sukuluetteloihin merkitty polveutumisensa mukaan, perhekuntapäämiestensä, väkevien sankareiden, mukaan, kaksikymmentä tuhatta kaksisataa.',
        10: 'Jediaelin poika oli Bilhan, ja Bilhanin pojat olivat Jeus, Benjamin, Eehud, Kenaana, Seetan, Tarsis ja Ahisahar.',
        11: 'Kaikki nämä olivat Jediaelin poikia perhekuntapäämiesten, väkevien sankareiden, mukaan; seitsemäntoista tuhatta kaksisataa sotakelpoista miestä.',
        12: 'Suppim ja Huppim olivat Iirin poikia; Huusim oli Aherin poika.',
        13: 'Naftalin pojat olivat Jahasiel, Guuni, Jeeser ja Sallum, Bilhan jälkeläisiä.',
        14: 'Manassen poika oli Asriel, jonka hänen aramilainen sivuvaimonsa synnytti. Tämä synnytti Maakirin, Gileadin isän.',
        15: 'Maakir otti vaimon Huppimille ja Suppimille, ja hänen sisarensa nimi oli Maaka. Toisen nimi oli Selofhad; ja Selofhadilla oli tyttäriä.',
        16: 'Maaka, Maakirin vaimo, synnytti pojan, jolle hän antoi nimen Peres; hänen veljensä nimi oli Seres, ja hänen poikansa olivat Uulam ja Rekem.',
        17: 'Uulamin poika oli Bedan. Nämä olivat Gileadin pojat, joka oli Maakirin poika, joka Manassen poika.',
        18: 'Hänen sisarensa Mooleket synnytti Iishodin, Abieserin ja Mahlan.',
        19: 'Semidan pojat olivat Ahjan, Sekem, Likhi ja Aniam.',
        20: 'Efraimin pojat olivat: Suutelah, tämän poika Bered, tämän poika Tahat, tämän poika Elada, tämän poika Tahat,',
        21: 'tämän poika Saabad, tämän poika Suutelah, sekä Eser ja Elead. Gatin miehet, siinä maassa syntyneet, tappoivat heidät, koska he olivat lähteneet ottamaan heidän karjaansa.',
        22: 'Heidän isänsä Efraim suri pitkät ajat, ja hänen veljensä tulivat lohduttamaan häntä.',
        23: 'Sitten hän yhtyi vaimoonsa, ja tämä tuli raskaaksi ja synnytti pojan. Hän antoi tälle nimen Beria, koska se oli tapahtunut hänen perheensä onnettomuuden aikana.',
        24: 'Hänen tyttärensä oli Seera. Tämä rakensi Ala- ja Ylä-Beet-Hooronin sekä Ussen-Seeran.',
        25: 'Berian poika oli Refah, samoin Resef, tämän poika Telah, tämän poika Tahan,',
        26: 'tämän poika Ladan, tämän poika Ammihud, tämän poika Elisama,',
        27: 'tämän poika Nuun ja tämän poika Joosua.',
        28: 'Heidän perintömaansa ja asuinpaikkansa olivat Beetel ja sen tytärkaupungit, itään Naaran ja länteen Geser ja sen tytärkaupungit, sekä Sikem ja sen tytärkaupungit, aina Aijaan ja sen tytärkaupunkeihin asti.',
        29: 'Manasselaisten hallussa olivat Beet-Sean ja sen tytärkaupungit, Taanak ja sen tytärkaupungit, Megiddo ja sen tytärkaupungit, Door ja sen tytärkaupungit. Näissä asuivat Joosefin, Israelin pojan, jälkeläiset.',
        30: 'Asserin pojat olivat Jimna, Jisva, Jisvi ja Beria, heidän sisarensa oli Serah.',
        31: 'Berian pojat olivat Heber ja Malkiel. Tämä oli Birsaitin isä.',
        32: 'Heberille syntyi Jaflet, Soomer, Hootam ja heidän sisarensa Suua.',
        33: 'Jafletin pojat olivat Paasak, Bimhal ja Asva. Nämä ovat Jafletin pojat.',
        34: 'Semerin pojat olivat Ahi, Rohga, Hubba ja Aram.',
        35: 'Hänen veljensä Heelemin pojat olivat Soofah, Jimna, Seeles ja Aamal.',
        36: 'Soofahin pojat olivat Suuah, Harnefer, Suual, Beeri, Jimra,',
        37: 'Beser, Hood, Samma, Silsa, Jitran ja Beera.',
        38: 'Jeterin pojat olivat Jefunne, Fispa ja Ara.',
        39: 'Ullan pojat olivat Aarah, Hanniel ja Risja.',
        40: 'Kaikki nämä olivat Asserin jälkeläisiä, perhekuntien päämiehiä, väkeviä sankareita, ruhtinaiden päämiehiä. Heidän sukuluetteloihin merkittyjen sotakelpoisten miestensä lukumäärä oli kaksikymmentäkuusi tuhatta.',
    },
    8: {
        1: 'Benjaminille syntyi esikoisena Bela, toisena Asbel, kolmantena Ahrah,',
        2: 'neljäntenä Nooha ja viidentenä Raafa.',
        3: 'Belalla oli pojat: Addar, Geera, Abihud,',
        4: 'Abisua, Naaman, Ahoah,',
        5: 'Geera, Sefufan ja Huuram.',
        6: 'Nämä olivat Eehudin pojat – nämä olivat Geban asukkaiden perhekuntien päämiehet. Heidät siirrettiin pois Manahatiin,',
        7: 'myös Naaman, Ahia ja Geera. Hän siirsi heidät pois. Hänelle syntyi Ussa ja Ahihud.',
        8: 'Saharaimille syntyi Mooabin maassa, sitten kun hän oli hylännyt vaimonsa Huusimin ja Baaran,',
        9: 'hänelle syntyi hänen vaimostaan Hoodeksesta Joobab, Sibja, Meesa, Malkam,',
        10: 'Jeus, Sokja ja Mirma. Nämä olivat hänen poikiansa, perhekuntien päämiehiä.',
        11: 'Huusimista oli hänelle syntynyt Abitub ja Elpaal.',
        12: 'Elpaalin pojat olivat Eeber, Misam ja Semed. Tämä rakensi Oonon ja Loodin sekä sen tytärkaupungit.',
        13: 'Beria ja Sema olivat Aijalonin asukkaiden perhekuntien päämiehiä. He karkottivat Gatin asukkaat,',
        14: 'he ja Ahjo, Saasak ja Jeremot.',
        15: 'Sebadja, Arad, Eder,',
        16: 'Miikael, Jispa ja Jooha olivat Berian poikia.',
        17: 'Sebadja, Mesullam, Hiski, Heber,',
        18: 'Jismerai, Jislia ja Joobab olivat Elpaalin poikia.',
        19: 'Jaakim, Sikri, Sabdi,',
        20: 'Elienai, Silletai, Eliel,',
        21: 'Adaja, Beraja ja Simrat olivat Siimein poikia.',
        22: 'Jispan, Eder, Eliel,',
        23: 'Abdon, Sikri, Haanan,',
        24: 'Hananja, Eelam, Antotia,',
        25: 'Jifdeja ja Penuel olivat Saasakin poikia.',
        26: 'Samserai, Seharja, Atalja,',
        27: 'Jaaresja, Elia ja Sikri olivat Jerohamin poikia.',
        28: 'Nämä olivat perhekuntien päämiehiä, päämiehiä polveutumisensa mukaan. He asuivat Jerusalemissa.',
        29: 'Gibeonissa asui Gibeonin isä, jonka vaimon nimi oli Maaka.',
        30: 'Hänen esikoispoikansa oli Abdon, sitten Suur, Kiis, Baal, Naadab,',
        31: 'Gedor, Ahjo ja Seker.',
        32: 'Miklotille syntyi Simea. Hekin asuivat veljineen Jerusalemissa, rajakkain veljiensä kanssa.',
        33: 'Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.',
        34: 'Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.',
        35: 'Miikan pojat olivat Piiton, Melek, Tarea ja Aahas.',
        36: 'Aahaalle syntyi Jooadda, Jooaddalle syntyi Aalemet, Asmavet ja Simri. Simrille syntyi Moosa,',
        37: 'ja Moosalle syntyi Binea. Hänen poikansa oli Raafa, tämän poika Elasa ja tämän poika Aasel.',
        38: 'Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä kaikki olivat Aaselin poikia.',
        39: 'Eesekin, hänen veljensä, pojat olivat: hänen esikoisensa Uulam, toinen Jeus ja kolmas Elifelet.',
        40: 'Uulamin pojat olivat väkeviä sankareita, jousen jännittäjiä, ja heillä oli paljon poikia ja poikien poikia, sataviisikymmentä. Nämä kaikki ovat benjaminilaisia.',
    },
    9: {
        1: 'Koko Israel merkittiin sukuluetteloon, ja katso, he ovat kirjoitetut Israelin kuningasten kirjaan. Mutta Juuda vietiin Baabeliin karkotukseen uskottomuutensa tähden.',
        2: 'Entiset asukkaat, jotka elivät perintömaillaan, kaupungeissaan, olivat israelilaisia, pappeja, leeviläisiä ja temppelipalvelijoita.',
        3: 'Jerusalemissa oli asunut Juudan lapsia, benjaminilaisia, efraimilaisia ja manasselaisia, nimittäin:',
        4: 'Uutai, Ammihudin poika, joka oli Omrin poika, joka Imrin poika, joka Baanin poika, Pereksen, Juudan pojan, jälkeläisiä;',
        5: 'seelalaisia: Asaja, esikoinen, ja hänen poikansa;',
        6: 'serahilaisia: Jeguel ja hänen veljensä, kuusisataa yhdeksänkymmentä;',
        7: 'benjaminilaisia: Sallu, Mesullamin poika, joka oli Hoodavjan poika, joka Senuan poika,',
        8: 'Jibneja, Jerohamin poika, Eela, Ussin poika, joka oli Mikrin poika, ja Mesullam, Sefatjan poika, joka oli Reguelin poika, joka Jibnean poika,',
        9: 'sekä heidän veljensä, heidän polveutumisensa mukaan, yhdeksänsataa viisikymmentä kuusi. Kaikki nämä olivat perhekuntien päämiehiä perhekunnissaan.',
        10: 'Pappeja: Jedaja, Joojarib, Jaakin,',
        11: 'Asarja, Hilkian poika, joka oli Mesullamin poika, joka Saadokin poika, joka Merajotin poika, joka Ahitubin poika, Jumalan temppelin esimies;',
        12: 'Adaja, Jerohamin poika, joka oli Pashurin poika, joka Malkian poika, ja Maesai, Adielin poika, joka oli Jahseran poika, joka Mesullamin poika, joka Mesillemitin poika, joka Immerin poika;',
        13: 'sekä heidän veljensä, heidän perhekuntiensa päämiehet, tuhat seitsemänsataa kuusikymmentä miestä, kelvollisia toimittamaan palvelusta Jumalan temppelissä.',
        14: 'Leeviläisiä: Semaja, Hassubin poika, joka oli Asrikamin poika, joka Hasabjan poika, merarilaisia;',
        15: 'Bakbakkar, Heres, Gaalal, Mattanja, Miikan poika, joka oli Sikrin poika, joka Aasafin poika;',
        16: 'Obadja, Semajan poika, joka oli Gaalalin poika, joka Jedutunin poika; ja Berekja, Aasan poika, joka oli Elkanan poika, hänen, joka asui netofalaisten kylissä.',
        17: 'Ovenvartijat: Sallum, Akkub, Talmon ja Ahiman veljineen: Sallum oli päämies,',
        18: 'ja tähän saakka hän on ollut vartijana Kuninkaan portilla, idän puolella. Nämä olivat ovenvartijoina leeviläisten leirissä.',
        19: 'Mutta Sallumilla, Kooren pojalla, joka oli Ebjasafin poika, joka Koorahin poika, ja hänen veljillään, jotka olivat hänen perhekuntaansa – koorahilaisilla, oli palvelustehtävänä telttamajan kynnysten vartioiminen; heidän isänsä olivat näet vartioineet sisäänkäyntiä Herran leirissä.',
        20: 'Piinehas, Eleasarin poika, oli muinoin heidän esimiehenään – Herra olkoon hänen kanssaan! –',
        21: 'Sakarja, Meselemjan poika, oli ovenvartijana ilmestysmajan ovella.',
        22: 'Kaikkiaan oli kynnysten ovenvartijoiksi valittuja kaksisataa kaksitoista. He olivat kylissään merkityt sukuluetteloon. Daavid ja Samuel, näkijä, olivat asettaneet heidät heidän luottamustoimeensa.',
        23: 'He ja heidän poikansa olivat vartijoina Herran temppelin, telttapyhäkön, ovilla.',
        24: 'Ovenvartijat olivat asetetut neljälle ilmansuunnalle: idän, lännen, pohjoisen ja etelän puolelle.',
        25: 'Heidän veljiensä, jotka asuivat kylissään, oli aina määräaikoina seitsemäksi päiväksi tultava toimittamaan palvelusta yhdessä heidän kanssaan.',
        26: 'Sillä nämä neljä ylintä ovenvartijaa olivat pysyvästi luottamustoimessaan. Nämä olivat leeviläisiä. Heidän oli myös valvottava kammioita ja Jumalan temppelin aarteita.',
        27: 'He viettivät yönsä Jumalan temppelin ympärillä, sillä heidän tehtävänään oli vartiointi ja heidän oli huolehdittava ovien avaamisesta joka aamu.',
        28: 'Muutamien heistä oli huolehdittava jumalanpalveluksessa tarvittavasta kalustosta, sillä heidän oli tuotava se sisään täysilukuisena ja vietävä se ulos täysilukuisena.',
        29: 'Muutamat heistä olivat määrätyt pitämään huolta kalustosta, koko pyhästä kalustosta, sekä ydinjauhoista, viinistä, öljystä, suitsukkeista ja hajuaineista.',
        30: 'Muutamat pappien pojista valmistivat voiteita hajuaineista.',
        31: 'Mattitjalla, joka oli leeviläisiä ja oli koorahilaisen Sallumin esikoinen, oli luottamustoimena leivonnaisten valmistus.',
        32: 'Muutamien kehatilaisista, heidän veljistään, oli huolehdittava näkyleivistä ja valmistettava ne joka sapatiksi.',
        33: 'Mutta veisaajat, leeviläisten perhekuntien päämiehet, oleskelivat kammioissa, muusta palveluksesta vapaina, sillä he olivat toimessa sekä päivällä että yöllä.',
        34: 'He olivat leeviläisten perhekuntien päämiehiä, päämiehiä polveutumisensa mukaan. He asuivat Jerusalemissa.',
        35: 'Gibeonissa asuivat Gibeonin isä, jonka vaimon nimi oli Maaka,',
        36: 'hänen esikoispoikansa Abjon, sitten Suur, Kiis, Baal, Neer, Naadab,',
        37: 'Gedor, Ahjo, Sakarja ja Mikleot.',
        38: 'Mikleotille syntyi Simeam. Hekin asuivat veljineen Jerusalemissa, rajakkain veljiensä kanssa.',
        39: 'Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.',
        40: 'Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.',
        41: 'Miikan pojat olivat Piiton, Melek ja Tahrea.',
        42: 'Aahaalle syntyi Jaera, Jaeralle syntyi Aalemet, Asmavet ja Simri. Simrille syntyi Moosa,',
        43: 'ja Moosalle syntyi Binea, hänen poikansa oli Refaja, tämän poika Elasa ja tämän poika Aasel.',
        44: 'Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä olivat Aaselin pojat.',
    },
    10: {
        1: 'Filistealaiset taistelivat Israelia vastaan, ja Israelin miehet pakenivat filistealaisia, ja heitä kaatui surmattuina Gilboan vuorella.',
        2: 'Filistealaiset pääsivät Saulin ja hänen poikiensa kintereille, ja filistealaiset surmasivat Joonatanin, Abinadabin ja Malkisuan, Saulin pojat.',
        3: 'Kun taistelu kiihtyi ankaraksi Saulia vastaan ja jousimiehet keksivät hänet, hän joutui hätään jousimiesten ahdistaessa.',
        4: 'Saul sanoi aseenkantajalleen: "Paljasta miekkasi ja lävistä sillä minut, etteivät nuo ympärileikkaamattomat tulisi pitämään minua pilkkanaan." Mutta hänen aseenkantajansa ei tahtonut, sillä hän pelkäsi kovin. Saul otti itse miekan ja heittäytyi siihen.',
        5: 'Mutta kun hänen aseenkantajansa näki, että Saul oli kuollut, hänkin heittäytyi miekkaansa ja kuoli.',
        6: 'Niin kuolivat Saul ja hänen kolme poikaansa sekä koko hänen perheensä. He kuolivat yhdessä.',
        7: 'Kun kaikki Israelin miehet, jotka asuivat tasangolla, huomasivat, että he olivat paenneet ja että Saul poikineen oli kuollut, he jättivät kaupunkinsa ja pakenivat, ja filistealaiset tulivat ja asettuivat niihin.',
        8: 'Seuraavana päivänä filistealaiset tulivat ryöstämään surmattuja ja löysivät Saulin ja hänen poikansa kaatuneina Gilboan vuorelta.',
        9: 'He ryöstivät hänet ja ottivat hänen päänsä ja hänen aseensa ja lähettivät ne ympäri filistealaisten maata julistaakseen voitonsanomaa epäjumalilleen ja kansalle.',
        10: 'He asettivat hänen aseensa jumalansa temppeliin, ja hänen pääkallonsa he kiinnittivät Daagonin temppeliin.',
        11: 'Kun koko Gileadin Jaabes kuuli, mitä kaikkea filistealaiset olivat tehneet Saulille,',
        12: 'he nousivat, kaikki asekuntoiset miehet, ja ottivat Saulin ja hänen poikiensa ruumiit ja toivat ne Jaabekseen. He hautasivat heidän luunsa tammen alle Jaabekseen ja paastosivat seitsemän päivää.',
        13: 'Saul kuoli, koska hän oli ollut uskoton Herraa kohtaan eikä ollut ottanut vaarin Herran sanasta, ja myös sen tähden, että hän oli kysynyt vainajahengeltä neuvoa,',
        14: 'mutta ei ollut kysynyt neuvoa Herralta. Sen tähden hän surmasi hänet ja siirsi kuninkuuden Daavidille, Iisain pojalle.',
    },
    11: {
        1: 'Koko Israel kokoontui Daavidin luo Hebroniin, ja he sanoivat: "Katso, me olemme luutasi ja lihaasi.',
        2: 'Jo kauan sitten Saulin vielä ollessa kuninkaana sinä sait Israelin lähtemään ja tulemaan. Sinulle on Herra, Jumalasi, sanonut: \'Sinä olet kaitseva kansaani Israelia, ja sinä olet oleva kansani Israelin ruhtinas.\'"',
        3: 'Kaikki Israelin vanhimmat tulivat kuninkaan luo Hebroniin, ja Daavid teki heidän kanssaan liiton Hebronissa Herran edessä. He voitelivat Daavidin Israelin kuninkaaksi sen sanan mukaan, jonka Herra oli puhunut Samuelin kautta.',
        4: 'Daavid ja koko Israel menivät Jerusalemiin, se on Jebukseen, ja siellä olivat jebusilaiset, jotka asuivat siinä maassa.',
        5: 'Jebuksen asukkaat sanoivat Daavidille: "Tänne et tule." Mutta Daavid valloitti Siionin Vuorilinnan, se on Daavidin kaupungin.',
        6: 'Daavid sanoi: "Joka ensimmäisenä surmaa jebusilaisen, hän on oleva päämies ja päällikkö." Jooab, Serujan poika, tuli ensimmäisenä sinne ylös, ja niin hänestä tuli päämies.',
        7: 'Daavid asettui Vuorilinnaan. Sen tähden sitä kutsuttiin Daavidin kaupungiksi.',
        8: 'Hän rakensi kaupunkia joka taholle, Millosta [vuoren] reunoihin asti. Jooab rakensi entiselleen muun osan kaupunkia.',
        9: 'Daavid tuli yhä suuremmaksi, ja Herra Sebaot oli hänen kanssaan.',
        10: 'Nämä ovat ensimmäiset Daavidin sankareista, jotka voimakkaasti auttoivat häntä kuninkuuteen yhdessä koko Israelin kanssa tehdäkseen hänet Israelin kuninkaaksi Herran sanan mukaan.',
        11: 'Tämä on Daavidin sankareiden luettelo: Jaasobeam, hakmonilaisen poika, niiden kolmen päällikkö, hän, joka oli heiluttanut keihästään kolmensadan kaatuneen yli yhdellä kertaa.',
        12: 'Hänen jälkeensä Eleasar, Doodon poika, ahohilainen, yksi niistä kolmesta sankarista.',
        13: 'Hän oli Daavidin kanssa Pas-Dammimissa, kun filistealaiset olivat kokoontuneet sinne sotimaan. Siellä oli peltopalsta täynnä ohraa. Väki pakeni filistealaisia,',
        14: 'mutta he asettuivat keskelle palstaa, saivat sen pelastetuksi ja voittivat filistealaiset. Herra antoi suuren pelastuksen.',
        15: 'Kerran lähti kolme noista kolmestakymmenestä päälliköstä Daavidin luo kalliolinnaan, Adullamin luolalle. Filistealaisten joukko oli leiriytynyt Refaimin tasangolle.',
        16: 'Daavid oli Vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.',
        17: 'Daavidin rupesi tekemään mieli vettä, ja hän sanoi: "Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!"',
        18: 'Nämä kolme murtautuivat filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat Daavidille. Mutta Daavid ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle',
        19: 'ja sanoi: "Pois se! Jumala varjelkoon minut sitä tekemästä. Joisinko minä näiden miesten verta, heidän henkeään, sillä henkensä uhalla he sen toivat." Eikä hän tahtonut juoda sitä. Tämän olivat tehneet nuo kolme sankaria.',
        20: 'Abisai, Jooabin veli, oli niiden kolmen päällikkö. Hän oli heiluttanut keihästään kolmensadan kaatuneen yli. Hän oli maineikas niiden kolmen joukossa.',
        21: 'Hän oli kaksinkertaisessa arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta hän ei vetänyt vertoja niille kolmelle.',
        22: 'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi kaksi mooabilaista sankaria, ja hän laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.',
        23: 'Hän surmasi myös egyptiläisen miehen, suurikasvuisen, viisi kyynärää pitkän miehen. Egyptiläisellä oli kädessä keihäs, joka oli kuin kangastukki, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.',
        24: 'Tällaisia teki Benaja, Joojadan poika. Hän oli kuulu näiden kolmen sankarin joukossa.',
        25: 'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta hän ei vetänyt vertoja niille kolmelle. Daavid asetti hänet henkivartiostonsa päälliköksi.',
        26: 'Sankarit olivat: Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;',
        27: 'harorilainen Sammot; pelonilainen Heeles;',
        28: 'tekoalainen Iira, Ikkeksen poika; anatotilainen Abieser;',
        29: 'huusalainen Sibbekai; ahohilainen Iilai;',
        30: 'netofalainen Maharai; netofalainen Heeled, Baanan poika;',
        31: 'Iitai, Riibain poika, benjaminilaisten Gibeasta, piratonilainen Benaja;',
        32: 'Huurai Nahale-Gaasista; arabalainen Abiel;',
        33: 'baharumilainen Asmavet; saalbonilainen Eljahba;',
        34: 'gisonilainen Bene-Haasem; hararilainen Joonatan, Saagen poika;',
        35: 'hararilainen Abijam, Saakarin poika; Elifal, Uurin poika;',
        36: 'mekeralainen Heefer; pelonilainen Ahia;',
        37: 'karmelilainen Hesro; Naarai, Esbain poika;',
        38: 'Jooel, Naatanin veli; Mibhar, Hagrin poika;',
        39: 'ammonilainen Selek; beerotilainen Nahrai, Jooabin, Serujan pojan aseenkantaja;',
        40: 'jeteriläinen Iira; jeteriläinen Gaareb;',
        41: 'heettiläinen Uuria; Saabad, Ahlain poika;',
        42: 'ruubenilainen Adina, Siisan poika, ruubenilaisten päämies, ja hänen kanssaan kolmekymmentä muuta;',
        43: 'Haanan, Maakan poika, ja mitniläinen Joosafat;',
        44: 'astarotilainen Ussia; Saama ja Jegiel, aroerilaisen Hootamin pojat;',
        45: 'Jediael, Simrin poika, ja hänen veljensä Jooha, tiisiläinen;',
        46: 'Eliel-Mahavim sekä Jeribai ja Joosavja, Elnaamin pojat, ja mooabilainen Jitma;',
        47: 'Eliel, Oobed ja Jaasiel-Mesobaja.',
    },
    12: {
        1: 'Nämä olivat ne, jotka tulivat Daavidin luo Siklagiin, kun hän vielä piileskeli Saulia, Kiisin poikaa. He olivat niitä sankareita, jotka auttoivat häntä sodassa.',
        2: 'He olivat aseistettuja jousella ja olivat taitavia sekä oikealla että vasemmalla kädellä linkoamaan kiviä ja ampumaan jousella nuolia. Saulin heimolaisia, benjaminilaisia:',
        3: 'Ahieser, päämies, ja Jooas, gibealaisen Hassemaan pojat; Jesiel ja Pelet, Asmavetin pojat; Beraka; anatotilainen Jeehu;',
        4: 'gibeonilainen Jismaja, sankari niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen päällikkö;',
        5: 'Jeremia; Jahasiel; Joohanan; gederalainen Joosabad;',
        6: 'Elusai; Jerimot; Bealja; Semarja; harufilainen Sefatja;',
        7: 'koorahilaiset Elkana, Jissia, Asarel, Jooeser ja Jaasobeam;',
        8: 'Jooela ja Sebadja, Jerohamin pojat, Gedrista.',
        9: 'Gaadilaisista meni Daavidin puolelle Vuorilinnaan, erämaahan, sankareita, sotakelpoisia miehiä, kilpeä ja keihästä käyttäviä, jotka olivat näöltään kuin leijonat ja nopeat kuin gasellit vuorilla:',
        10: 'Eeser, päämies Obadja toinen, Eliab kolmas,',
        11: 'Masmanna neljäs, Jeremia viides,',
        12: 'Attai kuudes, Eliel seitsemäs,',
        13: 'Joohanan kahdeksas, Elsabad yhdeksäs,',
        14: 'Jeremia kymmenes, Makbannai yhdestoista.',
        15: 'Nämä olivat gaadilaisia, sotajoukon päälliköitä, pienin sadan, suurin tuhannen miehen veroinen.',
        16: 'Nämä olivat ne, jotka ensimmäisessä kuussa menivät Jordanin poikki, kun se tulvi yli kaikkien äyräittensä, ja jotka karkottivat kaikki tasangoilla asujat itään ja länteen.',
        17: 'Myös benjaminilaisia ja Juudan miehiä tuli Daavidin Vuorilinnaan.',
        18: 'Daavid meni heitä vastaan, lausui ja sanoi heille: "Jos tulette luokseni rauha mielessä, auttaaksenne minua, sydämeni yhtyy teihin. Mutta jos tulette kavaltamaan minut vihollisilleni, vaikkei väkivalta tahraa käsiäni, isiemme Jumala nähköön sen ja rangaiskoon."',
        19: 'Mutta Henki täytti Amasain, niiden kolmenkymmenen päällikön, ja hän sanoi: "Sinun me olemme, Daavid, ja sinun puolellasi olemme, sinä Iisain poika. Rauha, rauha sinulle, ja rauha auttajillesi, sillä Jumalasi auttoi sinua!" Niin Daavid otti heidät vastaan ja asetti heidät partiojoukon päälliköiksi.',
        20: 'Manassesta siirtyi muutamia Daavidin puolelle, kun hän filistealaisten kanssa meni taistelemaan Saulia vastaan, vaikkeivät he joutuneetkaan auttamaan näitä, sillä filistealaisten ruhtinaat neuvoteltuaan lähettivät hänet [Daavidin] pois sanoen: "Hän voisi päämme menoksi siirtyä herransa Saulin puolelle."',
        21: 'Kun hän siis lähti Siklagiin, siirtyivät hänen puolelleen Manassesta: Adna, Joosabad, Jediael, Miikael, Joosabad, Elihu ja Silletai, tuhannenpäämiehet Manassesta.',
        22: 'Nämä auttoivat Daavidia rosvojoukkoa vastaan, sillä he olivat kaikki sankareita, ja heistä tuli sotajoukon päälliköitä.',
        23: 'Sillä joka päivä tuli väkeä Daavidin luo auttamaan häntä, kunnes joukko oli suuri kuin Jumalan joukko.',
        24: 'Tämä on sotaan varustetun aseväen lukumäärä, niiden, jotka tulivat Daavidin luo Hebroniin siirtääkseen Saulin kuninkuuden hänelle Herran käskyn mukaan:',
        25: 'Juudan miehiä, jotka kantoivat kilpeä ja keihästä, kuusituhatta kahdeksansataa, sotaan varustettua;',
        26: 'simeonilaisia, väkeviä sankareita, seitsemäntuhatta sata;',
        27: 'leeviläisiä neljätuhatta kuusisataa,',
        28: 'sekä Joojada, Aaronin suvun ruhtinas, sekä kolmetuhatta seitsemänsataa hänen kanssaan;',
        29: 'ja Saadok, nuorukainen, väkevä sankari, perhekuntineen, kaksikymmentä kaksi päällikköä;',
        30: 'benjaminilaisia, Saulin veljiä, kolmetuhatta, sillä vielä siihen aikaan suurin osa heistä palveli uskollisesti Saulin sukua',
        31: 'efraimilaisia kaksikymmentä tuhatta kahdeksansataa, väkeviä sankareita, nimekkäitä miehiä perhekunnissaan;',
        32: 'toisesta puolesta Manassen sukukuntaa kahdeksantoista tuhatta, jotka olivat nimeltä mainitut menemään ja tekemään Daavidin kuninkaaksi;',
        33: 'isaskarilaisia, jotka ymmärsivät ajan ja käsittivät, mitä Israelin oli tehtävä, kaksisataa päämiestä, ja kaikki heidän veljensä heidän johdollaan;',
        34: 'Sebulonista sotakelpoisia miehiä, kaikkinaisilla sota-aseilla sotaan varustettuja, viisikymmentä tuhatta, yksimielisiä taistelurintamaan järjestymään;',
        35: 'Naftalista tuhat päällikköä, ja heidän kanssaan kolmekymmentäseitsemän tuhatta kilvellä ja keihäällä varustettua miestä;',
        36: 'daanilaisia kaksikymmentäkahdeksan tuhatta kuusisataa sotaan varustettua miestä;',
        37: 'Asserista sotakelpoisia miehiä, taisteluun valmiita, neljäkymmentä tuhatta;',
        38: 'tuolta puolelta Jordanin, ruubenilaisia, gaadilaisia ja manasselaisia sukukunnan toisesta puolesta, satakaksikymmentä tuhatta, kaikilla sota-aseilla varustettuja.',
        39: 'Kaikki nämä sotilaat, taistelurintamaan järjestyneinä, tulivat ehyellä sydämen halulla Hebroniin tehdäkseen Daavidin koko Israelin kuninkaaksi. Myös koko muu Israel oli yksimielinen tehdäkseen Daavidin kuninkaaksi.',
        40: 'He olivat siellä Daavidin luona kolme päivää ja söivät ja joivat, sillä heidän heimolaisensa olivat antaneet heille evästä.',
        41: 'Nekin, jotka asuivat lähellä heitä, aina Isaskariin, Sebuloniin ja Naftaliin saakka, toivat aasien, kamelien, muulien ja härkien selässä ruokatavaraa: jauhoja, viikunakakkuja ja rusinakakkuja, viiniä ja öljyä, nautoja ja lampaita ja vuohia hyvin runsaasti, sillä Israelissa oli ilo.',
    },
    13: {
        1: 'Daavid neuvotteli tuhannen- ja sadanpäämiesten, kaikkien ruhtinasten, kanssa.',
        2: 'Daavid sanoi kaikelle Israelin seurakunnalle: "Jos teistä on hyvä ja jos se tulee Herralta, Jumalaltamme, lähettäkäämme joka taholle sana veljillemme, jotka ovat jääneet kaikkiin Israelin maakuntiin, ja papeille ja leeviläisille, jotka asuvat heidän luonaan laidunmaittensa kaupungeissa, että he kokoontuvat luoksemme,',
        3: 'ja siirtäkäämme Jumalamme arkki luoksemme, sillä Saulin päivinä emme siitä välittäneet."',
        4: 'Koko seurakunta vastasi, että niin oli tehtävä, sillä se oli oikein koko kansan silmissä.',
        5: 'Daavid kokosi koko Israelin, aina Egyptin Siihorista asti ja aina sieltä, mistä mennään Hamatiin, tuomaan Jumalan arkkia Kirjat-Jearimista.',
        6: 'Daavid ja koko Israel meni Baalatiin, Kirjat-Jearimiin, joka on Juudassa, tuomaan sieltä Jumalan arkkia, jonka Herra oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.',
        7: 'He panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, ja Ussa ja Ahjo ohjasivat vaunuja.',
        8: 'Daavid sekä koko Israel karkeloivat kaikin voimin Jumalan edessä laulaen sekä soittaen lyyraa, harppuja, tamburiineja, symbaaleja ja torvia.',
        9: 'Mutta kun he tulivat Kiidonin puimatantereen luo, Ussa ojensi kätensä tarttuakseen arkkiin, sillä härät kompastuivat.',
        10: 'Herran viha syttyi Ussaa kohtaan, ja hän löi häntä sen tähden, että hän oli ojentanut kätensä arkkiin, ja hän kuoli siihen, Jumalan eteen.',
        11: 'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä paikan nimenä on Peres-Ussa vielä tänäkin päivänä.',
        12: 'Daavid pelästyi sinä päivänä Jumalaa, niin että hän sanoi: "Kuinka voin tuoda Jumalan arkin luokseni?"',
        13: 'Eikä Daavid siirtänyt arkkia luokseen Daavidin kaupunkiin, vaan toimitti sen syrjään gatilaisen Oobed-Edomin taloon.',
        14: 'Jumalan arkki jäi kolmeksi kuukaudeksi Oobed-Edomin talon luo. Herra siunasi Oobed-Edomin taloa ja kaikkea, mitä hänellä oli.',
    },
    14: {
        1: 'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo, sekä setripuita ja puuseppiä ja kivenhakkaajia rakentamaan hänelle linnaa.',
        2: 'Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi, koska hänen kuninkuutensa oli korotettu korkealle Herran kansan Israelin tähden.',
        3: 'Jerusalemissa Daavid vielä otti vaimoja, ja Daavidille syntyi vielä poikia ja tyttäriä.',
        4: 'Nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,',
        5: 'Jibhar, Elisua, Elpelet,',
        6: 'Noogah, Nefeg, Jaafia,',
        7: 'Elisama, Beeljada ja Elifelet.',
        8: 'Mutta kun filistealaiset kuulivat, että Daavid oli voideltu koko Israelin kuninkaaksi, kaikki filistealaiset lähtivät etsimään Daavidia. Kun Daavid kuuli sen, hän lähti heitä vastaan.',
        9: 'Kun filistealaiset olivat tulleet ja tehneet ryöstöretken Refaimin tasangolle,',
        10: 'Daavid kysyi Jumalalta: "Menenkö filistealaisia vastaan, ja annatko heidät käsiini?" Herra sanoi hänelle: "Mene. Annan heidät käsiisi."',
        11: 'He menivät Baal-Perasimiin, ja siellä Daavid voitti heidät. Daavid sanoi: "Jumala on murtanut viholliseni kädelläni, niin kuin vedet murtavat." Siitä sen paikan nimeksi tuli Baal-Perasim.',
        12: 'Filistealaiset jättivät siihen jumalansa, ja Daavid käski polttaa ne tulessa.',
        13: 'Filistealaiset tekivät kuitenkin vielä kerran ryöstöretken tasangolle.',
        14: 'Daavid kysyi taas Jumalalta, ja Jumala vastasi hänelle: "Älä mene heidän jälkeensä, vaan kierrä heidät ja hyökkää heidän kimppuunsa balsamipuiden puolelta.',
        15: 'Kun kuulet askelten äänen balsamipuiden latvoista, käy taisteluun, sillä Jumala on käynyt edelläsi tuhotakseen filistealaisten leirin."',
        16: 'Daavid teki, niin kuin Jumala oli häntä käskenyt, ja he voittivat filistealaisten sotajoukon ja ajoivat heitä takaa Gibeonista aina Geseriin saakka.',
        17: 'Daavidin maine levisi kaikkiin maihin, ja Herra nosti kaikissa kansoissa pelon häntä kohtaan.',
    },
    15: {
        1: 'Hän rakensi itselleen taloja Daavidin kaupunkiin ja valmisti paikan Jumalan arkille ja pystytti sille telttamajan.',
        2: 'Daavid käski: "Älkööt muut kuin leeviläiset kantako Jumalan arkkia, sillä heidät Herra on valinnut kantamaan Jumalan arkkia ja palvelemaan häntä ikiajoiksi."',
        3: 'Daavid kokosi koko Israelin Jerusalemiin, tuomaan Herran arkin siihen paikkaan, jonka hän oli sille valmistanut.',
        4: 'Daavid kokosi Aaronin jälkeläiset ja leeviläiset;',
        5: 'Kehatin jälkeläisistä: Uurielin, päämiehen, ja hänen veljensä, sata kaksikymmentä;',
        6: 'Merarin jälkeläisistä: Asajan, päämiehen, ja hänen veljensä, kaksisataa kaksikymmentä;',
        7: 'Geersomin jälkeläisistä: Jooelin, päämiehen, ja hänen veljensä, sata kolmekymmentä;',
        8: 'Elisafanin jälkeläisistä: Semajan, päämiehen, ja hänen veljensä, kaksisataa;',
        9: 'Hebronin jälkeläisistä: Elielin, päämiehen, ja hänen veljensä, kahdeksankymmentä;',
        10: 'Ussielin jälkeläisistä: Amminadabin, päämiehen, ja hänen veljensä, sata kaksitoista.',
        11: 'Daavid kutsui papit Saadokin ja Ebjatarin sekä leeviläiset Uurielin, Asajan, Jooelin, Semajan, Elielin ja Amminadabin',
        12: 'ja sanoi heille: "Te olette leeviläisten perhekuntien päämiehet. Pyhittäkää itsenne ja veljenne ja tuokaa Herran, Israelin Jumalan, arkki siihen paikkaan, jonka olen sille valmistanut',
        13: 'Sillä sen tähden, ettette ensimmäisellä kerralla olleet läsnä, mursi Herra, meidän Jumalamme, meidät. Sillä me emme etsineet häntä, niin kuin olisi pitänyt."',
        14: 'Papit ja leeviläiset pyhittäytyivät tuomaan Herran, Israelin Jumalan, arkin.',
        15: 'Leeviläiset kantoivat Jumalan arkkia korennoilla olallaan, kuten Mooses oli Herran sanan mukaan käskenyt.',
        16: 'Daavid käski leeviläisten päämiesten asettaa veljensä, veisaajat, soittimilla, lyyroilla, harpuilla ja symbaaleilla kaiuttamaan riemuvirsiä.',
        17: 'Leeviläiset asettivat soittamaan Heemanin, Jooelin pojan, ja hänen heimolaisistaan Aasafin, Berekjan pojan, ja heidän heimolaisistaan, Merarin jälkeläisistä, Eetanin, Kuusajan pojan,',
        18: 'ja heidän kanssaan heidän arvossa lähinnä olevista heimolaisistaan: Sakarjan, Benin ja Jaasielin, Semiramotin, Jehielin, Unnin, Eliabin, Benajan, Maasejan, Mattitjan, Elifelehun, Miknejan, Oobed-Edomin ja Jegielin, ovenvartijat.',
        19: 'Veisaajista oli Heemanin, Aasafin ja Eetanin soitettava vaskisymbaaleilla,',
        20: 'Sakarjan, Ussielin, Semiramotin, Jehielin, Unnin, Eliabin, Maasejan ja Benajan harpuilla korkeassa äänialassa,',
        21: 'Mattitjan, Elifelehun, Miknejan, Oobed-Edomin, Jegielin ja Asasjan sitroilla matalassa äänialassa, veisuuta johtaakseen.',
        22: 'Kenanja, leeviläisten johtaja kantajatehtävässä, valvoi kantamista, sillä hän oli siinä taitava.',
        23: 'Berekja ja Elkana olivat arkin ovenvartijat.',
        24: 'Papit Sebanja, Joosafat, Netanel, Amasai, Sakarja, Benaja ja Elieser puhalsivat torviin Jumalan arkin edellä, ja Oobed-Edom ja Jehia olivat arkin ovenvartijat.',
        25: 'Daavid, Israelin vanhimmat ja tuhannenpäämiehet menivät ja toivat riemuiten Herran liitonarkin Oobed-Edomin talosta.',
        26: 'Kun Jumala auttoi leeviläisiä, jotka kantoivat Herran liitonarkkia, uhrattiin seitsemän härkää ja seitsemän pässiä.',
        27: 'Daavid oli puettu hienosta pellavakankaasta tehtyyn viittaan ja samoin kaikki leeviläiset, jotka kantoivat arkkia, sekä veisaajat ja kantamisen johtaja Kenanja veisaajien kanssa. Daavidilla oli yllään pellavakasukka.',
        28: 'Koko Israel toi Herran liitonarkin riemun raikuessa ja torvien raikuessa, torvien, symbaalien, harppujen ja lyyrojen soidessa.',
        29: 'Kun Herran liitonarkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta, ja nähdessään kuningas Daavidin hyppivän ja karkeloivan hän halveksi häntä sydämessään.',
    },
    16: {
        1: 'Kun he olivat tuoneet Jumalan arkin ja asettaneet sen telttamajaan, jonka Daavid oli sille pystyttänyt, he uhrasivat polttouhreja ja rauhanuhreja Jumalan edessä.',
        2: 'Kun Daavid oli uhrannut polttouhrin ja rauhanuhrit, hän siunasi kansan Herran nimeen.',
        3: 'Hän jakoi kaikille israelilaisille, sekä miehille että naisille, kullekin leipäkakun, palan lihaa ja rypälekakun.',
        4: 'Hän asetti Herran arkin eteen leeviläisiä palvelemaan ja kunnioittamaan, kiittämään ja ylistämään Herraa, Israelin Jumalaa:',
        5: 'Aasafin johtajaksi, toiseksi Sakarjan, sitten Jegielin, Semiramotin, Jehielin, Mattitjan, Eliabin, Benajan, Oobed-Edomin ja Jegielin soittamaan harpuilla ja lyyroilla, Aasafin helistäessä symbaaleja',
        6: 'ja pappien, Benajan ja Jahasielin, soittaessa taukoamatta torvia Jumalan liitonarkin edessä.',
        7: 'Silloin, sinä päivänä, Daavid asetti Aasafin ja hänen veljensä ensi kerran kiittämään Herraa näin:',
        8: '"Kiittäkää Herraa, julistakaa hänen nimeään, tehkää hänen suuret tekonsa tiettäviksi kansojen keskuudessa',
        9: 'Laulakaa hänelle, veisatkaa hänelle, puhukaa kaikista hänen ihmeistään.',
        10: 'Kerskatkaa hänen pyhässä nimessään. Iloitkoon niiden sydän, jotka Herraa etsivät.',
        11: 'Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojaan.',
        12: 'Muistakaa hänen ihmetekojaan, jotka hän on tehnyt, hänen ihmeitään ja hänen suunsa tuomioita,',
        13: 'te Israelin, hänen palvelijansa, siemen, Jaakobin lapset, te hänen valittunsa.',
        14: 'Hän, Herra, on Jumalamme. Hänen tuomionsa käyvät yli koko maan.',
        15: 'Muistakaa hänen liittonsa iankaikkisesti, hamaan tuhansiin polviin, sana, jonka hän on säätänyt,',
        16: 'liitto, jonka hän teki Aabrahamin kanssa, ja hänen Iisakille vannomansa vala.',
        17: 'Hän vahvisti sen käskyksi Jaakobille, Israelille ikuiseksi liitoksi.',
        18: "Hän sanoi: 'Sinulle annan Kanaanin maan. Olkoon se perintöosanne.'",
        19: 'Teitä oli vähäinen joukko, vain harvoja, ja te olitte siellä muukalaisia.',
        20: 'He vaelsivat kansasta kansaan ja yhdestä valtakunnasta toiseen kansakuntaan.',
        21: 'Hän ei sallinut kenenkään heitä vahingoittaa, ja hän rankaisi kuninkaita heidän tähtensä:',
        22: "'Älkää koskeko Messiaaseeni, älkää tehkö pahaa Profeetalleni.'",
        23: 'Veisatkaa Herralle, kaikki maa, julistakaa päivästä päivään hänen pelastustekojaan.',
        24: 'Ilmoittakaa pakanoiden keskellä hänen kunniansa, hänen ihmeensä kaikkien kansojen seassa.',
        25: 'Sillä Herra on suuri ja sangen ylistettävä, hän on pelottava yli kaikkien jumalien.',
        26: 'Sillä kaikki pakanakansojen jumalat ovat epäjumalia, mutta Herra on tehnyt taivaat.',
        27: 'Kirkkaus ja kunnia on hänen kasvojensa edessä, väkevyys ja riemu hänen asuinsijassaan.',
        28: 'Antakaa Herralle, te kansojen sukukunnat, antakaa Herralle kunnia ja väkevyys.',
        29: 'Antakaa Herralle hänen nimensä kunnia, tuokaa lahjoja ja tulkaa hänen kasvojensa eteen, kumartakaa Herraa pyhässä kaunistuksessa.',
        30: 'Vaviskaa hänen kasvojensa edessä, kaikki maa. Maanpiiri pysyy lujana eikä horju.',
        31: "Iloitkoot taivaat, ja riemuitkoon maa, ja sanottakoon pakanoiden keskuudessa: ' Herra on kuningas!'",
        32: 'Pauhatkoon meri ja kaikki, mitä siinä on. Ihastukoot kedot ja kaikki, mitä niissä on,',
        33: 'riemuitkoot silloin metsän puut Herran edessä, sillä hän saapuu tuomitsemaan maata.',
        34: 'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.',
        35: "Sanokaa: 'Pelasta meidät, sinä pelastuksemme Jumala, kokoa ja vapahda meidät pakanoiden seasta, että kiittäisimme sinun pyhää nimeäsi ja kerskaisimme ylistyksestäsi.'",
        36: 'Ylistetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen." Kaikki kansa sanoi: "Aamen", ja ylisti Herraa.',
        37: 'Hän [Daavid] asetti Aasafin ja hänen veljensä Herran liitonarkin eteen tekemään vakituista palvelusta arkin edessä, kunakin päivänä sen päivän palveluksen,',
        38: 'mutta Oobed-Edomin ja heidän veljensä, yhteensä kuusikymmentä kahdeksan, nimittäin Oobed-Edomin, Jeditunin pojan, ja Hoosan, ovenvartijoiksi.',
        39: 'Pappi Saadokin ja hänen veljensä, papit, hän asetti Herran asumuksen eteen, uhrikukkulalle, joka on Gibeonissa,',
        40: 'uhraamaan polttouhreja Herralle polttouhrialttarilla, aina aamuin ja illoin, kaikki niin kuin on kirjoitettuna Herran laissa, jonka hän on antanut Israelille.',
        41: 'Heidän kanssaan olivat Heeman ja Jedutun sekä muut valitut, nimeltä mainitut, kiittämässä Herraa siitä, että hänen armonsa pysyy iankaikkisesti.',
        42: 'Näiden, Heemanin ja Jedutunin, hallussa oli torvet ja symbaalit soittajia varten sekä muut soittimet Jumalan virttä varten. Jedutunin pojat vartioivat ovia.',
        43: 'Kaikki kansa lähti kukin kotiinsa, ja Daavid kääntyi takaisin siunaamaan perhettään.',
    },
    17: {
        1: 'Kerran kun Daavid istui linnassaan, Daavid sanoi profeetta Naatanille: "Katso, minä asun setripuisessa palatsissa, mutta Herran liitonarkki on telttakankaan alla." Naatan sanoi Daavidille:',
        2: '"Tee vain kaikki, mitä mielessäsi on, sillä Jumala on kanssasi."',
        3: 'Mutta tapahtui sinä yönä, että Naatanille tuli tämä Jumalan sana:',
        4: '"Mene ja sano palvelijalleni Daavidille: Näin sanoo Herra: Sinä et ole rakentava minulle temppeliä siinä asuakseni.',
        5: 'Sillä en ole asunut temppelissä siitä päivästä asti, jona johdatin Israelin tänne, tähän päivään saakka, vaan olen muuttanut teltasta telttaan ja asumuksesta asumukseen.',
        6: 'Olenko missään, missä olenkin vaeltanut kaikessa Israelissa, sanonut kenellekään Israelin tuomareista, joita olen asettanut kaitsemaan kansaani: Miksi ette ole rakentaneet minulle setripuista huonetta?',
        7: 'Sano siis palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta lammasten jäljestä kansani Israelin ruhtinaaksi.',
        8: 'Olen ollut kanssasi kaikkialla, missä vaelsit, ja olen hävittänyt kaikki vihollisesi tieltäsi. Teen sinulle nimen, suurimpien nimien vertaisen maan päällä.',
        9: 'Valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallaan eikä ole enää levoton eivätkä vääryydentekijät vaivaa sitä enää kuten ennen,',
        10: 'siitä ajasta saakka, jolloin asetin tuomareita kansalleni Israelille. Nöyryytän kaikki vihollisesi. Ilmoitan sinulle, että Herra on rakentava sinulle temppelin.',
        11: 'Kun päiväsi ovat päättyneet lähteäksesi isiesi luo, korotan seuraajaksesi jälkeläisesi, joka on yksi pojistasi, ja vahvistan hänen kuninkuutensa.',
        12: 'Hän on rakentava minulle temppelin, ja vahvistan hänen valtaistuimensa ikiajoiksi.',
        13: 'Minä olen oleva hänen Isänsä, ja hän on oleva minun Poikani, ja armoani en häneltä ota pois, niin kuin otin siltä, joka oli edelläsi.',
        14: 'Pidän hänet pystyssä huoneessani ja valtakunnassani iäti, ja hänen valtaistuimensa on oleva iäti vahva."',
        15: 'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.',
        16: 'Kuningas Daavid meni ja asettui Herran eteen ja sanoi: "Mikä olen minä, Herra Jumala, ja mikä on sukuni, että olet saattanut minut tähän asti?',
        17: 'Mutta tämäkin on ollut vähän sinun silmissäsi, Jumala, ja niin olet puhunut palvelijasi suvusta kaukaisina tulevina aikoina ja olet nähnyt minut ylennettynä ihmiskyyhkynä, joka on Herra Jumala.',
        18: 'Mitä Daavid enää sinulle puhuisi kunniasta, jota olet osoittanut palvelijallesi? Sinähän tunnet palvelijasi.',
        19: 'Herra, palvelijasi tähden ja oman mielesi mukaan sinä olet tehnyt kaiken tämän suuren ja ilmoittanut kaikki nämä suuret asiat.',
        20: 'Herra, kaiken sen mukaan, mitä me olemme korvillamme kuulleet, ei ole vertaistasi, eikä ole muuta jumalaa kuin sinä.',
        21: 'Missä on maan päällä toista kansaa kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansakseen ja tehdäkseen itselleen suuren ja pelottavan nimen karkottamalla pakanat kansasi tieltä, jonka Egyptistä lunastit.',
        22: 'Olet asettanut kansasi Israelin omaksi kansaksesi ikuisiksi ajoiksi, ja sinä, Herra, olet heidän Jumalansa.',
        23: 'Olkoon nyt, Herra, se sana, jonka sinä olet puhunut palvelijastasi ja hänen suvustaan, vahva ikuisiksi ajoiksi. Tee, niin kuin olet puhunut.',
        24: 'Nimesi on oleva vahva ja tuleva suureksi ikuisiksi ajoiksi, ja se on oleva: Herra Sebaot, Israelin Jumala, Jumala Israelissa. Palvelijasi Daavidin suku on pysyvä edessäsi.',
        25: 'Sillä sinä, Jumalani, olet ilmoittanut palvelijallesi rakentavasi hänelle temppelin. Siitä palvelijasi on saanut rohkeuden rukoilla edessäsi.',
        26: 'Nyt, Herra, sinä olet Jumala. Kun olet luvannut palvelijallesi tämän hyvän,',
        27: 'suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti edessäsi. Sillä se, minkä sinä, Herra, siunaat, on oleva siunattu iäti."',
    },
    18: {
        1: 'Sen jälkeen Daavid voitti filistealaiset ja nöyryytti heidät. Hän otti Gatin ja sen tytärkaupungit filistealaisten käsistä.',
        2: 'Hän voitti myös mooabilaiset, ja mooabilaiset tulivat Daavidin veronalaisiksi palvelijoiksi.',
        3: 'Samoin Daavid voitti Hadareserin, Sooban kuninkaan, Hamatin suunnalla, kun tämä oli menossa lujittamaan valtaansa Eufrat-virran rannoille.',
        4: 'Daavid otti häneltä tuhat vaunuhevosta, seitsemäntuhatta ratsumiestä ja kaksikymmentä tuhatta jalkamiestä, ja Daavid katkoi kaikilta vaunuhevosilta vuohisjänteet. Ainoastaan sata vaunuhevosta hän niistä säästi.',
        5: 'Kun Damaskon aramilaiset tulivat auttamaan Hadareseria, Sooban kuningasta, Daavid voitti kaksikymmentäkaksi tuhatta aramilaista.',
        6: 'Daavid asetti maaherroja Damaskon Aramiin, ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa tämä meni.',
        7: 'Daavid otti ne kultavarustukset, jotka Hadareserin palvelijoilla oli yllään, ja vei ne Jerusalemiin.',
        8: 'Mutta Hadareserin kaupungeista, Tibhatista ja Kuunista, Daavid otti erittäin paljon vaskea. Siitä Salomo teetti vaskimeren, pylväät ja vaskiesineet.',
        9: 'Kun Toou, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadareserin, Sooban kuninkaan, koko sotajoukon,',
        10: 'hän lähetti poikansa Hadoramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadareserin kanssa ja voittanut hänet. Hadareser oli näet ollut Tooun vastustaja. Hänellä oli mukanaan kaikenlaisia kulta-, hopea- ja vaskiesineitä.',
        11: 'Nekin kuningas Daavid pyhitti Herralle samoin kuin hopean ja kullan, minkä hän oli ottanut kaikilta kansoilta: Edomilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta.',
        12: 'Kun Abisai, Serujan poika, oli Suolalaaksossa voittanut edomilaiset, kahdeksantoista tuhatta miestä,',
        13: 'hän asetti maaherroja Edomiin, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Herra antoi Daavidille voiton, mihin tahansa Daavid meni.',
        14: 'Daavid hallitsi koko Israelia ja teki kaikelle kansalleen sitä, mikä on oikeus ja vanhurskaus.',
        15: 'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.',
        16: 'Saadok, Ahitubin poika, ja Abimelek, Ebjatarin poika, olivat pappeina, ja Savsa oli kirjurina.',
        17: 'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä, mutta Daavidin pojat olivat ensimmäiset kuninkaan rinnalla.',
    },
    19: {
        1: 'Sen jälkeen ammonilaisten kuningas Naahas kuoli, ja hänen poikansa tuli kuninkaaksi hänen jälkeensä.',
        2: 'Daavid sanoi: "Minä osoitan laupeutta Haanunille, Naahaan pojalle, sillä hänen isänsä osoitti laupeutta minulle." Daavid lähetti sanansaattajat lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan Haanunin luo lohduttamaan häntä,',
        3: 'ammonilaisten päämiehet sanoivat Haanunille: "Kunnioittaako Daavid isääsi, kun hän lähettää lohduttajia luoksesi? Varmaankin hänen palvelijansa ovat tulleet luoksesi tutkimaan ja hävittämään ja vakoilemaan maata."',
        4: 'Haanun otatti kiinni Daavidin palvelijat, ajatti heidän partansa ja leikkautti toisen puolen heidän vaatteistaan, lonkkia myöten, ja lähetti heidät menemään.',
        5: 'Kun tultiin kertomaan Daavidille miehistä, hän lähetti sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Kuningas käski sanoa: "Jääkää Jerikoon, kunnes partanne on kasvanut, ja palatkaa."',
        6: 'Kun ammonilaiset huomasivat joutuneensa Daavidin vihoihin, Haanun ja ammonilaiset lähettivät tuhat talenttia hopeaa palkatakseen itselleen Mesopotamiasta, Maakan Aramista ja Soobasta sotavaunuja ja ratsumiehiä.',
        7: 'He palkkasivat itselleen kolmekymmentäkaksi tuhatta sotavaunua sekä Maakan kuninkaan ja hänen väkensä. Nämä tulivat ja leiriytyivät Meedeban edustalle. Ammonilaiset kokoontuivat kaupungeistaan ja lähtivät sotaan.',
        8: 'Kun Daavid kuuli sen, hän lähetti Jooabin ja koko sankareiden sotajoukon.',
        9: 'Ammonilaiset lähtivät ja asettuivat sotarintamaan kaupungin portin edustalle, mutta kuninkaat, jotka olivat tulleet sinne, olivat eri joukkona kedolla.',
        10: 'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, hän valitsi miehiä kaikista Israelin valioista ja asettui rintamaan aramilaisia vastaan.',
        11: 'Mutta muun väen hän antoi veljensä Abisain johtoon. Nämä asettuivat taistelurintamaan ammonilaisia vastaan.',
        12: 'Hän sanoi: "Jos aramilaiset tulevat minulle ylivoimaisiksi, niin tule avukseni: jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, autan sinua.',
        13: 'Ole luja, ja pysykäämme lujina kansamme puolesta ja Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee."',
        14: 'Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.',
        15: 'Kun ammonilaiset näkivät aramilaisten pakenevan, hekin pakenivat hänen veljeään Abisaita ja menivät kaupunkiin. Mutta Jooab lähti Jerusalemiin.',
        16: 'Kun aramilaiset näkivät, että Israel oli voittanut heidät, he lähettivät sanansaattajat nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran ja joita johti Soofak, Hadareserin sotapäällikkö.',
        17: 'Kun se ilmoitettiin Daavidille, hän kokosi koko Israelin ja meni Jordanin yli, ja tultuaan heitä lähelle hän asettui sotarintamaan heitä vastaan. Kun Daavid oli asettunut rintamaan aramilaisia vastaan, nämä ryhtyivät taisteluun hänen kanssaan.',
        18: 'Mutta aramilaiset pakenivat Israelia, ja Daavid tappoi aramilaisilta seitsemäntuhatta vaunuhevosta ja neljäkymmentä tuhatta jalkamiestä ja surmasi heidän sotapäällikkönsä Soofakin.',
        19: 'Kun Hadareserin palvelijat näkivät, että Israel oli voittanut heidät, he tekivät Daavidin kanssa rauhan ja palvelivat häntä. Aramilaiset eivät enää tahtoneet auttaa ammonilaisia.',
    },
    20: {
        1: 'Vuoden vaihteessa kuningasten sotaanlähtöaikaan Jooab vei sotajoukon sotaretkelle ja hävitti ammonilaisten maata ja piiritti Rabbaa. Mutta Daavid itse jäi Jerusalemiin. Jooab valtasi Rabban ja hävitti sen.',
        2: 'Daavid otti heidän kuninkaansa kruunun hänen päästään ja havaitsi sen painavan talentin kultaa. Siinä oli kallis kivi. Kruunu pantiin Daavidin päähän. Hän vei kaupungista hyvin paljon saalista.',
        3: 'Kansan, joka oli siellä, hän vei pois ja pani sahaamaan kiviä, pani rautahakkujen ja kivisahojen ääreen. Näin Daavid teki kaikille ammonilaisten kaupungeille. Daavid ja kaikki väki palasi Jerusalemiin.',
        4: 'Sen jälkeen syttyi taistelu filistealaisia vastaan Geserissä. Huusalainen Sibbekai surmasi Sippain, joka oli Raafan jälkeläisiä, ja heidät nöyryytettiin.',
        5: 'Taas oli taistelu filistealaisia vastaan, ja Elhanan, Jaaorin poika, surmasi Lahmin, gatilaisen Goljatin veljen, jonka peitsen varsi oli kuin kangastukki.',
        6: 'Taas oli taistelu Gatissa. Siellä oli suurikasvuinen mies, jolla oli kuusi sormea ja kuusi varvasta, yhteensä kaksikymmentä neljä. Hänkin polveutui Raafasta.',
        7: 'Kun hän häpäisi Israelia, hänet surmasi Joonatan, Daavidin veljen Simean poika.',
        8: 'Nämä polveutuivat gatilaisesta Raafasta. He kaatuivat Daavidin ja hänen palvelijoidensa käden kautta.',
    },
    21: {
        1: 'Mutta saatana nousi Israelia vastaan ja yllytti Daavidin laskemaan Israelin.',
        2: 'Daavid sanoi Jooabille ja kansan päämiehille: "Menkää ja laskekaa Israel Beersebasta Daaniin asti ja ilmoittakaa minulle, että saan tietää heidän lukumääränsä."',
        3: 'Jooab vastasi: " Herra lisätköön kansansa, olkoon se kuinka suuri tahansa, satakertaiseksi. Ovathan he, herrani, kuningas, kaikki herrani palvelijoita. Miksi herrani pyytää tätä? Miksi Israel näin joutuisi vikapääksi?"',
        4: 'Kuitenkin kuninkaan sana velvoitti Jooabia, ja Jooab lähti ja kierteli koko Israelin. Sitten hän tuli Jerusalemiin.',
        5: 'Jooab ilmoitti Daavidille kansan lasketun lukumäärän: koko Israelissa oli miljoona satatuhatta sotakuntoista miekkamiestä, ja Juudassa oli neljäsataa seitsemänkymmentä tuhatta miekkamiestä.',
        6: 'Leevistä ja Benjaminista hän ei pitänyt katselmusta yhdessä muiden kanssa, sillä kuninkaan käsky oli Jooabille kauhistus.',
        7: 'Mutta tämä asia oli Jumalan silmissä paha, ja hän löi Israelia.',
        8: 'Daavid sanoi Jumalalle: "Minä olen tehnyt suuren synnin tehdessäni tämän. Mutta anna nyt anteeksi palvelijasi rikos, sillä olen menetellyt hyvin tyhmästi."',
        9: 'Herra puhui Gaadille, Daavidin näkijälle, näin: "Mene ja puhu Daavidille:',
        10: 'Näin sanoo Herra: Kolme minä asetan eteesi: valitse itsellesi niistä yksi, teen sen sinulle."',
        11: 'Niin Gaad meni Daavidin luo ja sanoi hänelle: "Näin sanoo Herra: Valitse itsellesi',
        12: 'joko kolme nälkävuotta tai kolme kuukautta hävitystä ahdistajaisi vainotessa, vihollistesi miekka kintereilläsi, tai kolmeksi päiväksi Herran miekka ja rutto maahan, Herran enkeli tuottamaan tuhoa koko Israelin alueelle. Katso nyt, mitä minä vastaan hänelle, joka minut lähetti."',
        13: 'Daavid vastasi Gaadille: "Olen suuressa hädässä. Tahdon langeta Herran käsiin, sillä hänen laupeutensa on sangen suuri, – ihmisten käsiin en tahdo langeta."',
        14: 'Niin Herra antoi ruton tulla Israeliin, ja Israelista kaatui seitsemänkymmentä tuhatta miestä.',
        15: 'Jumala lähetti enkelin Jerusalemia vastaan tuhoamaan sitä. Kun se sitä tuhosi, Herra katsoi siihen ja katui sitä pahaa ja sanoi tuhoojaenkelille: "Jo riittää, laske kätesi alas." Herran enkeli seisoi silloin jebusilaisen Ornanin puimatantereen luona.',
        16: 'Kun Daavid nosti silmänsä ja näki Herran enkelin seisovan maan ja taivaan välillä, kädessään paljastettu miekka ojennettuna Jerusalemin yli, Daavid ja vanhimmat lankesivat säkkeihin verhottuina kasvoilleen.',
        17: 'Daavid sanoi Jumalalle: "Minähän käskin laskea kansan, ja minä siis olen se, joka olen tehnyt syntiä ja menetellyt pahoin. Mutta nämä lampaani, mitä he ovat tehneet? Herra, Jumalani, sattukoon kätesi minuun ja isäni perheeseen, mutta ei sinun kansaasi, sille vitsaukseksi."',
        18: 'Herran enkeli käski Gaadin sanoa Daavidille, että Daavid menisi pystyttämään Herralle alttarin jebusilaisen Ornanin puimatantereelle.',
        19: 'Daavid meni sen sanan mukaan, jonka Gaad oli Herran nimeen puhunut.',
        20: 'Kun Ornan kääntyi, hän näki enkelin, ja hänen neljä poikaansa piiloutui, sillä Ornan oli puimassa vehnää.',
        21: 'Mutta Daavid meni Ornanin luo, ja kun Ornan katsoi ylös ja näki Daavidin, hän lähti puimatantereelta ja kumartui Daavidin eteen kasvoilleen maahan.',
        22: 'Daavid sanoi Ornanille: "Anna minulle puimatantereen paikka rakentaakseni siihen Herralle alttarin. Anna se minulle täydestä hinnasta, että vitsaus taukoaisi kansasta."',
        23: 'Ornan vastasi Daavidille: "Ota se itsellesi, ja herrani, kuningas, tehköön, mitä hyväksi näkee. Katso, annan härät polttouhriksi ja puimaäkeet polttopuiksi sekä vehnänjyvät ruokauhriksi. Annan ne kaikki."',
        24: 'Mutta kuningas Daavid sanoi Ornanille: "Ei niin, vaan totisesti ostan ne sinulta täydestä hinnasta. Sillä minä en ota Herralle sitä, mikä on sinun, enkä uhraa ilmaiseksi saatua polttouhria."',
        25: 'Daavid antoi Ornanille siitä paikasta kuudensadan sekelin painon kultaa.',
        26: 'Daavid rakensi sinne alttarin Herralle ja uhrasi polttouhreja ja rauhanuhreja, ja kun hän huusi Herraa, vastasi Herra tulella, jonka hän lähetti taivaasta polttouhrialttarille.',
        27: 'Herra käski enkelin pistää miekkansa tuppeen.',
        28: 'Siihen aikaan kun Daavid näki, että Herra oli kuullut häntä jebusilaisen Ornanin puimatantereella, hän uhrasi siellä.',
        29: 'Mutta Herran asumus, jonka Mooses oli teettänyt erämaassa, ja polttouhrialttari olivat siihen aikaan Gibeonin uhrikukkulalla.',
        30: 'Eikä Daavid rohjennut mennä Jumalan eteen etsimään häntä, sillä hän oli pelästynyt Herran enkelin miekkaa.',
    },
    22: {
        1: 'Daavid sanoi: "Tässä olkoon Herran Jumalan temppeli ja tässä alttari Israelin polttouhria varten."',
        2: 'Daavid käski koota muukalaiset, jotka olivat Israelin maassa. Hän asetti kivenhakkaajia hakkaamaan kiviä Jumalan temppelin rakentamiseksi.',
        3: 'Daavid hankki paljon rautaa portin ovien nauloiksi ja sinkilöiksi ja niin paljon vaskea, ettei se ollut punnittavissa,',
        4: 'sekä suunnattomat määrät setripuita, sillä siidonilaiset ja tyyrolaiset toivat paljon setripuita Daavidille.',
        5: 'Sillä Daavid ajatteli: "Poikani Salomo on nuori ja hento, mutta Herralle rakennettavan temppelin tulee olla hyvin suuri, niin että sitä mainitaan ja kiitetään kaikissa maissa. Minä siis hankin hänelle varastot." Daavid hankki ennen kuolemaansa suuret varastot.',
        6: 'Hän kutsui poikansa Salomon ja käski hänen rakentaa temppelin Herralle, Israelin Jumalalle.',
        7: 'Daavid sanoi Salomolle: "Poikani, minä aioin itse rakentaa temppelin Herran, Jumalani, nimelle.',
        8: "Mutta minulle tuli tämä Herran sana: 'Sinä olet vuodattanut paljon verta ja käynyt suuria sotia. Sinä et ole rakentava temppeliä nimelleni, koska olet vuodattanut niin paljon verta maahan edessäni.",
        9: 'Katso, sinulle on syntyvä poika. Hänestä on tuleva rauhan mies, ja annan hänen päästä rauhaan kaikilta hänen ympärillään asuvilta vihollisilta, sillä Salomo on oleva hänen nimensä, ja minä annan rauhan ja levon Israelille hänen päivinään.',
        10: "Hän on rakentava temppelin minun nimelleni. Hän on oleva poikani, ja minä olen oleva hänen Isänsä. Minä vahvistan hänen kuninkuutensa valtaistuimen ikiajoiksi.'",
        11: 'Olkoon siis Herra kanssasi, poikani, että menestyisit ja saisit rakennetuksi temppelin Herralle, Jumalallesi, niin kuin hän on sinusta puhunut.',
        12: 'Antakoon vain Herra sinulle älyä ja ymmärrystä ja asettakoon sinut hallitsemaan Israelia ja noudattamaan Herran, Jumalasi, lakia.',
        13: 'Silloin menestyt, jos tarkasti noudatat niitä käskyjä ja oikeuksia, jotka Herra antoi Moosekselle Israelia varten. Ole luja ja rohkea, älä pelkää äläkä arkaile.',
        14: 'Katso, vaivanalaisenakin olen hankkinut Herran temppeliä varten satatuhatta talenttia kultaa ja tuhat kertaa tuhat talenttia hopeaa sekä vaskea ja rautaa niin paljon, ettei se ole punnittavissa, sillä sitä on erittäin paljon. Olen myös hankkinut hirsiä ja kiviä, ja sinä saat hankkia vielä lisää.',
        15: 'Paljon on sinulla myös työmiehiä, kivenhakkaajia, muurareita, puuseppiä ja kaikenlaisen työn taitajia.',
        16: 'Kullalla, hopealla, vaskella ja raudalla ei ole määrää. Nouse, ryhdy työhön, ja Herra olkoon kanssasi!"',
        17: 'Daavid käski kaikkia Israelin päämiehiä auttamaan poikaansa Salomoa sanoen:',
        18: '"Onhan Herra, Jumalanne, ollut kanssanne ja suonut teidän päästä joka taholla rauhaan, sillä hän on antanut maan asukkaat käsiini ja maa on tehty alamaiseksi Herralle ja hänen kansalleen.',
        19: 'Antakaa siis sydämenne ja sielunne etsimään Herraa, Jumalaanne. Nouskaa ja rakentakaa Herran, Jumalan, pyhäkkö, että Herran liitonarkki ja Jumalan pyhä kalusto voitaisiin viedä temppeliin, joka on rakennettava Herran nimelle."',
    },
    23: {
        1: 'Kun Daavid oli tullut vanhaksi ja saanut elämästä kylliksi, hän teki poikansa Salomon Israelin kuninkaaksi.',
        2: 'Hän kutsui kokoon kaikki Israelin päämiehet, papit ja leeviläiset.',
        3: 'Leeviläiset laskettiin, kolmekymmentävuotiaat ja sitä vanhemmat, ja heidän lukumääränsä pääluvun mukaan oli kolmekymmentäkahdeksan tuhatta miestä.',
        4: '"Näistä olkoon kaksikymmentäneljä tuhatta johtamassa töitä Herran temppelissä ja kuusi tuhatta päällysmiehinä ja tuomareina.',
        5: 'Neljä tuhatta olkoon ovenvartijoina, ja neljä tuhatta ylistäköön Herraa soittimilla, jotka olen teettänyt ylistämistä varten."',
        6: 'Daavid jakoi heidät osastoihin Leevin poikien Geersonin, Kehatin ja Merarin mukaan.',
        7: 'Geersonilaisia olivat Ladan ja Siimei.',
        8: 'Ladanin pojat olivat Jehiel, päämies, Seetam ja Jooel, kaikkiaan kolme.',
        9: 'Siimein pojat olivat Selomit, Hasiel ja Haaran, kaikkiaan kolme. Nämä olivat Ladanin perhekuntien päämiehet.',
        10: 'Siimein pojat olivat Jahat, Siina, Jeus ja Beria. Nämä olivat Siimein pojat, kaikkiaan neljä.',
        11: 'Jahat oli päämies, Siisa toinen, mutta Jeuksella ja Berialla ei ollut monta poikaa, niin että heistä tuli yksi perhekunta, yksi palvelusvuoro.',
        12: 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel, kaikkiaan neljä.',
        13: 'Amramin pojat olivat Aaron ja Mooses. Mutta Aaron poikineen erotettiin olemaan ikuisesti pyhitetty, korkeasti pyhä, ikuisesti suitsuttamaan Herran edessä, palvelemaan häntä ja siunaamaan hänen nimessään.',
        14: 'Jumalan miehen Mooseksen pojat luettiin Leevin sukukuntaan kuuluviksi.',
        15: 'Mooseksen pojat olivat Geersom ja Elieser.',
        16: 'Geersomin poika oli Sebuel, päämies.',
        17: 'Elieserin poika oli Rehabja, päämies. Elieserillä ei ollut muita poikia. Mutta Rehabjan poikia oli hyvin paljon.',
        18: 'Jisharin poika oli Selomit, päämies.',
        19: 'Hebronin pojat olivat Jeria, päämies, Amarja toinen, Jahasiel kolmas ja Jekamam neljäs.',
        20: 'Ussielin pojat olivat Miika, päämies, ja Jissia toinen.',
        21: 'Merarin pojat olivat Mahli ja Muusi. Mahlin pojat olivat Eleasar ja Kiis.',
        22: 'Kun Eleasar kuoli, häneltä ei jäänyt poikia, vaan ainoastaan tyttäriä, jotka heidän serkkunsa, Kiisin pojat, ottivat vaimoikseen.',
        23: 'Muusin pojat olivat Mahli, Eeder ja Jeremot, kaikkiaan kolme.',
        24: 'Nämä olivat Leevin pojat, heidän perhekuntiensa mukaan, perhekuntien päämiehet, niin monta kuin heitä oli ollut katselmuksessa, nimien lukumäärän mukaan, pääluvun mukaan, ne, jotka toimittivat palvelustehtäviä Herran temppelissä, kaksikymmentävuotiaat ja sitä vanhemmat.',
        25: 'Sillä Daavid sanoi: " Herra, Israelin Jumala, on suonut kansansa päästä lepoon ja on asuva Jerusalemissa ikuisesti.',
        26: 'Niinpä ei leeviläistenkään tarvitse kantaa asumusta eikä mitään esineitä, joita tarvitaan siinä tehtävissä töissä."',
        27: '– Sillä Daavidin viimeisten määräysten mukaan laskettiin Leevin poikien lukuun kaksikymmentävuotiaat ja sitä vanhemmat. –',
        28: 'Heidän tehtäväkseen tuli: olla Aaronin poikien apuna Herran temppelin töissä, pitää huoli esikartanoista ja kammioista, kaiken pyhän puhtaana pitämisestä ja Jumalan temppelin töistä,',
        29: 'näkyleivistä, ruokauhriin tarvittavista ydinjauhoista, happamattomista ohuista leivistä, leivinlevystä ja jauhosekoituksesta sekä astia- ja pituusmitoista,',
        30: 'seisoa joka aamu kiittämässä ja ylistämässä Herraa, ja samoin joka ilta,',
        31: 'ja uhrata kaikki polttouhrit Herralle sapatteina, uudenkuun päivinä ja juhlina, niin paljon kuin niitä oli säädetty aina uhrattavaksi Herran edessä.',
        32: 'Heidän oli hoidettava ilmestysmajan ja pyhäkön tehtävät sekä ne tehtävät, jotka heidän veljillään Aaronin pojilla oli palvellessaan Herran temppelissä.',
    },
    24: {
        1: 'Nämä olivat Aaronin poikien osastot: Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.',
        2: 'Naadab ja Abihu kuolivat ennen isäänsä, eikä heillä ollut poikia. Pappeina palvelivat ainoastaan Eleasar ja Iitamar.',
        3: 'Daavid yhdessä Saadokin kanssa, joka oli Eleasarin poikia, ja Ahimelekin kanssa, joka oli Iitamarin poikia, jakoi heidät osastoihin heidän palvelusvuorojensa mukaan.',
        4: 'Kun Eleasarin pojilla havaittiin olevan enemmän päämiehiä kuin Iitamarin pojilla, heidät jaettiin niin, että Eleasarin pojat saivat kuusitoista päämiestä perhekunnilleen ja Iitamarin pojat kahdeksan päämiestä perhekunnilleen.',
        5: 'Heidät jaettiin arvalla, toiset niin kuin toisetkin, sillä pyhäkköruhtinaat ja Jumalan ruhtinaat otettiin sekä Eleasarin pojista että Iitamarin pojista.',
        6: 'Semaja, Netanelin poika, kirjuri, joka oli Leevin sukua, kirjoitti heidät muistiin kuninkaan, päämiesten, pappi Saadokin ja Ahimelekin, Ebjatarin pojan, sekä pappien ja leeviläisten perhekuntien päämiesten läsnäollessa. Yksi perhekunta otettiin vuorotellen Eleasarin ja Iitamarin suvusta.',
        7: 'Ensimmäinen arpa tuli Joojaribille, toinen Jedajalle,',
        8: 'kolmas Haarimille, neljäs Seoromille,',
        9: 'viides Malkialle, kuudes Miijaminille,',
        10: 'seitsemäs Koosille, kahdeksas Abialle,',
        11: 'yhdeksäs Jeesualle, kymmenes Sekanjalle,',
        12: 'yhdestoista Eljasibille, kahdestoista Jaakimille,',
        13: 'kolmastoista Huppalle, neljästoista Jesebabille,',
        14: 'viidestoista Bilgalle, kuudestoista Immerille,',
        15: 'seitsemästoista Heesirille, kahdeksastoista Pissekselle,',
        16: 'yhdeksästoista Petahjalle, kahdeskymmenes Hesekielille,',
        17: 'kahdeskymmenes ensimmäinen Jaakinille, kahdeskymmenes toinen Gaamulille,',
        18: 'kahdeskymmenes kolmas Delajalle ja kahdeskymmenes neljäs Maasjalle.',
        19: 'Nämä ovat heidän palvelusvuoronsa, kun he menevät Herran temppeliin, niin kuin heidän isänsä Aaron oli heille säätänyt, sen mukaan, kuin Herra, Israelin Jumala, oli häntä käskenyt.',
        20: 'Mitä tulee muihin Leevin jälkeläisiin, niin oli Amramin jälkeläisiä Suubael, Suubaelin jälkeläisiä Jehdeja,',
        21: 'Rehabjan jälkeläisiä päämies Jissia,',
        22: 'jisharilaisia Selomot, Selomotin jälkeläisiä Jahat.',
        23: 'Jerian jälkeläisiä olivat: Amarja toinen, Jahasiel kolmas, Jekamam neljäs.',
        24: 'Ussielin jälkeläisiä oli Miika, Miikan jälkeläisiä Saamir.',
        25: 'Miikan veli oli Jissia. Jissian jälkeläisiä oli Sakarja.',
        26: 'Merarin jälkeläisiä olivat Mahli ja Muusi sekä hänen poikansa Jaasian jälkeläiset.',
        27: 'Merarilla oli jälkeläisiä pojastaan Jaasiasta sekä Sooham, Sakkur ja Ibri.',
        28: 'Mahlista polveutui Eleasar, jolla ei ollut poikia.',
        29: 'Kiisistä polveutui Jerahmeel, joka oli Kiisin jälkeläisiä.',
        30: 'Muusin jälkeläisiä olivat Mahli, Eeder ja Jerimot. Nämä olivat leeviläisten jälkeläiset heidän perhekuntiensa mukaan.',
        31: 'Myös nämä, niin hyvin perhekuntien päämiehet kuin heidän nuoremmat veljensä, heittivät arpaa samoin kuin heidän veljensä, Aaronin pojat, kuningas Daavidin, Saadokin ja Ahimelekin sekä pappien ja leeviläisten perhekuntien päämiesten läsnä ollessa.',
    },
    25: {
        1: 'Daavid ja sotapäälliköt erottivat palvelukseen Aasafin, Heemanin ja Jedutunin pojat, jotka profetoivat lyyroilla, harpuilla ja symbaaleilla. Tämä on luettelo miehistä, jotka toimittivat tätä palvelustaan:',
        2: 'Aasafin poikia oli Sakkur, Joosef, Netanja ja Asarela, Aasafin pojat, Aasafin johdolla, joka profetoi kuninkaan johdolla.',
        3: 'Jedutunista: Jedutunin pojat Gedalja, Seri, Jesaja, Hasabja ja Mattitja, kaikkiaan kuusi, isänsä Jedutunin johdolla, joka profetoi lyyralla kiittäen ja ylistäen Herraa.',
        4: 'Heemanista: Heemanin pojat Bukkia, Mattanja, Ussiel, Sebuel ja Jerimot, Hananja, Hanani, Eliata, Giddalti ja Roomamti-Eser, Josbekasa, Malloti, Hootir ja Mahasiot.',
        5: 'Nämä ovat kaikki Heemanin, kuninkaan näkijän, poikia, sen Jumalan sanan mukaan, että hän on korottava korkealle hänen sarvensa: Jumala oli antanut Heemanille neljätoista poikaa ja kolme tytärtä.',
        6: 'Nämä kaikki veisasivat isänsä johdon alaisina Herran temppelissä symbaalien, harppujen ja lyyrojen säestäessä, Jumalan temppelipalveluksessa, kuninkaan, Aasafin, Jedutunin ja Heemanin johdolla.',
        7: 'Heidän ja heidän veljiensä lukumäärä, jotka oli opetettu veisaamaan Herran kunniaksi, kaikkien taitajien, oli kaksisataa kahdeksankymmentä kahdeksan.',
        8: 'He heittivät arpaa palvelusjärjestyksestä, nuoremmat niin kuin vanhemmatkin, taitajat yhdessä oppilaiden kanssa.',
        9: 'Ensimmäinen arpa, Aasafin arpa, tuli Joosefille. Toinen Gedaljalle, hänelle itselleen sekä hänen veljilleen ja pojilleen, joita oli kaikkiaan kaksitoista.',
        10: 'Kolmas Sakkurille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        11: 'Neljäs Jisrille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        12: 'Viides Netanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        13: 'Kuudes Bukkialle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        14: 'Seitsemäs Jesarelalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        15: 'Kahdeksas Jesajalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        16: 'Yhdeksäs Mattanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        17: 'Kymmenes Siimeille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        18: 'Yhdestoista Asarelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        19: 'Kahdestoista Hasabjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        20: 'Kolmastoista Suubaelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        21: 'Neljästoista Mattitjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        22: 'Viidestoista Jeremotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        23: 'Kuudestoista Hananjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        24: 'Seitsemästoista Josbekasalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        25: 'Kahdeksastoista Hananille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        26: 'Yhdeksästoista Mallotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        27: 'Kahdeskymmenes Elijjatalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        28: 'Kahdeskymmenes ensimmäinen Hootirille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        29: 'Kahdeskymmenes toinen Giddaltille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        30: 'Kahdeskymmenes kolmas Mahasiotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
        31: 'Kahdeskymmenes neljäs Roomamti-Eserille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.',
    },
    26: {
        1: 'Mitä tulee ovenvartijoiden osastoihin, niin oli koorahilaisia Meselemja, Kooren poika, Aasafin jälkeläisiä.',
        2: 'Meselemjalla oli pojat: esikoinen Sakarja, toinen Jediael, kolmas Sebadja, neljäs Jatniel,',
        3: 'viides Eelam, kuudes Joohanan, seitsemäs Eljoenai.',
        4: 'Oobed-Edomilla oli pojat: esikoinen Semaja, toinen Joosabad, kolmas Jooah, neljäs Saakar, viides Netanel,',
        5: 'kuudes Ammiel, seitsemäs Isaskar, kahdeksas Peulletai, sillä Jumala oli siunannut häntä.',
        6: 'Hänen pojalleen Semajalle syntyi poikia, jotka hallitsivat isänsä sukua, sillä he olivat kykeneviä miehiä.',
        7: 'Semajan pojat olivat Otni, Refael, Oobed ja Elsabad ja hänen veljensä, kykeneviä miehiä, Elihu ja Semakja.',
        8: 'Kaikki nämä olivat Oobed-Edomin jälkeläisiä, he sekä heidän poikansa ja veljensä, kykeneviä miehiä, tarmokkaita palveluksessaan, kaikkiaan kuusikymmentä kaksi Oobed-Edomin jälkeläistä.',
        9: 'Meselemjalla oli poikia ja veljiä, kykeneviä miehiä, kaikkiaan kahdeksantoista.',
        10: 'Hoosalla, joka oli Merarin jälkeläisiä, oli poikia: päämies Simri, jonka hänen isänsä, kun ei ollut esikoista, asetti päämieheksi;',
        11: 'toinen Hilkia, kolmas Tebalja, neljäs Sakarja; Hoosan poikia ja veljiä oli kaikkiaan kolmetoista.',
        12: 'Näiden ovenvartijain osastojen, päämiesten, samoin kuin heidän veljiensä, tehtävänä oli vartiopalvelus, sillä heidän oli palveltava Herran temppelissä.',
        13: 'He heittivät arpaa joka ovesta, nuoremmat niin kuin vanhemmatkin, perhekuntiensa mukaan.',
        14: 'Itäpuolen arpa lankesi Selemjalle, myös hänen pojalleen Sakarjalle, joka oli ymmärtäväinen neuvonantaja, heitettiin arpa, ja hänelle tuli pohjoispuolen arpa.',
        15: 'Oobed-Edomille määräsi arpa etelän ja hänen pojilleen varastohuoneen.',
        16: 'Suppimille ja Hoosalle lännen, jossa on Salleket-portti ylöspäin kohoavan tien kohdalla: vartiopaikan toisen vartiopaikan viereen.',
        17: 'Idän puolella oli kuusi leeviläistä, pohjoisen puolella neljä joka päivä, etelän puolella neljä joka päivä ja varastohuoneen luona kaksi ja kaksi.',
        18: 'Parparin luona, lännen puolella, oli neljä tiellä ja kaksi Parparin luona.',
        19: 'Nämä ovat ovenvartijoiden osastot, koorahilaisten jälkeläisten ja Merarin jälkeläisten.',
        20: 'Leeviläisistä hoiti Ahia Jumalan temppelin aarrekammioita ja pyhien lahjojen aarteita.',
        21: 'Ladanin pojat, geersonilaisten jälkeläiset, Ladanista polveutuvat geersonilaisen Ladanin perhekuntien päämiehet, jehieliläiset,',
        22: 'jehieliläisten jälkeläiset, olivat Seetam ja hänen veljensä Jooel. He hoitivat Herran temppelin aarrekammioita.',
        23: 'Mitä tulee amramilaisiin, jisharilaisiin, hebronilaisiin ja ossielilaisiin,',
        24: 'niin Sebuel, Geersomin poika, joka oli Mooseksen poika, oli aarrekammioiden esimies.',
        25: 'Hänen Elieseristä polveutuvat veljensä olivat: tämän poika Rehabja, tämän poika Jesaja, tämän poika Jooram, tämän poika Sikri ja tämän poika Selomot.',
        26: 'Tämä Selomot ja hänen veljensä hoitivat kaikkia niiden pyhien lahjojen aarteita, jotka kuningas Daavid, perhekuntien päämiehet, tuhannen- ja sadanpäämiehet ja sotapäälliköt olivat pyhittäneet.',
        27: 'Sodista ja saaliista he olivat ne pyhittäneet Herran temppelin voimassapitämiseksi.',
        28: 'Samoin kaikki, mitä Samuel, näkijä, Saul, Kiisin poika, Abner, Neerin poika, ja Jooab, Serujan poika, olivat pyhittäneet, kaikki, mikä pyhitettiin, jätettiin Selomitin ja hänen veljiensä hoitoon.',
        29: 'Jisharilaisista määrättiin Kenanja ja hänen poikansa maallisiin toimiin Israelissa, päällysmiehiksi ja tuomareiksi.',
        30: 'Hebronilaisista määrättiin Hasabja ja hänen veljensä, tuhat seitsemänsataa kykenevää miestä, Israelin hallinnon hoitoon Jordanin länsipuolella, kaikkiin Herran toimiin ja kuninkaan palvelukseen.',
        31: 'Hebronilaisia oli Jeria, hebronilaisten päämies, heidän polveutumisensa ja isiensä mukaan – Daavidin neljäntenäkymmenentenä hallitusvuotena heidät tutkittiin ja heidän joukostaan tavattiin kykeneviä miehiä Gileadin Jaeserissa –',
        32: 'sekä hänen veljensä, kaksituhatta seitsemänsataa kykenevää miestä, perhekuntien päämiehiä. Heidät kuningas Daavid asetti johtamaan ruubenilaisia, gaadilaisia ja toista puolta manasselaisten sukukuntaa kaikissa Jumalan ja kuninkaan asioissa.',
    },
    27: {
        1: 'Israelilaisia, lukumääränsä mukaan, sekä perhekuntapäämiehiä, tuhannen- ja sadanpäämiehiä ja heidän päällysmiehiään, jotka palvelivat kuningasta kaikessa, mikä koski osastoja, jotka tulivat ja lähtivät kuukausi kuukaudelta, vuoden kaikkina kuukausina, oli kussakin osastossa kaksikymmentäneljä tuhatta miestä:',
        2: 'Ensimmäisen osaston, ensimmäisen kuukauden osaston, johtajana oli Jaasobeam, Sabdielin poika, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        3: 'Hän oli Pereksen jälkeläisiä ja oli kaikkien sotapäällikköjen ylipäällikkö, ensimmäisenä kuukautena.',
        4: 'Toisen kuukauden osaston johtajana oli ahohilainen Doodai. Hänen osastonsa johdossa oli myös ruhtinas Miklot, ja hänen osastossaan oli kaksikymmentä neljä tuhatta.',
        5: 'Kolmas sotapäällikkö, kolmantena kuukautena, oli Benaja, pappi Joojadan poika, ylipäällikkö, ja hänen osastossaan oli kaksikymmentä neljä tuhatta.',
        6: 'Tämä Benaja oli sankari niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen johtaja, ja hänen osastossaan oli hänen poikansa Ammisabad.',
        7: 'Neljäs, neljäntenä kuukautena, oli Asahel, Jooabin veli, ja hänen jälkeensä hänen poikansa Sebadja; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        8: 'Viides, viidentenä kuukautena, oli päällikkö Samhut, jisrahilainen, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        9: 'Kuudes, kuudentena kuukautena, oli tekoalainen Iira, Ikkeksen poika, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        10: 'Seitsemäs, seitsemäntenä kuukautena, oli pelonilainen Heeles, efraimilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        11: 'Kahdeksas, kahdeksantena kuukautena, oli huusalainen Sibbekai, serahilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        12: 'Yhdeksäs, yhdeksäntenä kuukautena, oli anatotilainen Abieser, benjaminilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        13: 'Kymmenes, kymmenentenä kuukautena, oli netofalainen Mahrai, serahilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        14: 'Yhdestoista, yhdentenätoista kuukautena, oli piratonilainen Benaja, efraimilaisia, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        15: 'Kahdestoista, kahdentenatoista kuukautena, oli netofalainen Heldai, Otnielista polveutuva, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.',
        16: 'Israelin sukukuntien johtajat olivat: ruubenilaisten ruhtinas oli Elieser, Sikrin poika, simeonilaisten Sefatja, Maakan poika,',
        17: 'Leevin oli Hasabja, Kemuelin poika; Aaronin Saadok,',
        18: 'Juudan oli Elihu, Daavidin veljiä, Isaskarin Omri, Miikaelin poika,',
        19: 'Sebulonin oli Jismaja, Obadjan poika, Naftalin Jerimot, Asrielin poika,',
        20: 'efraimilaisten oli Hoosea, Asasjan poika, toisen puolen Manassen sukukuntaa Jooel, Pedajan poika,',
        21: 'toisen puolen Manassea, Gileadissa, oli Jiddo, Sakarjan poika, Benjaminin Jaasiel, Abnerin poika,',
        22: 'Daanin Asarel, Jerohamin poika. Nämä olivat Israelin sukukuntien ruhtinaat.',
        23: 'Daavid ei ottanut luetteloon kaksikymmenvuotiaita ja sitä nuorempia, sillä Herra oli luvannut tehdä Israelin monilukuiseksi kuin taivaan tähdet.',
        24: 'Jooab, Serujan poika, oli aloittanut laskemisen, mutta ei sitä lopettanut, sillä siitä viha kohtasi Israelia, eikä luku tullut kuningas Daavidin aikakirjaan.',
        25: 'Kuninkaan varastojen hoitaja oli Asmavet, Adielin poika. Kedolla, kaupungeissa, kylissä ja torneissa olevien varastojen hoitaja oli Joonatan, Ussian poika.',
        26: 'Maatöitä tekevien peltotyömiesten kaitsija oli Esri, Kelubin poika.',
        27: 'Viinitarhan hoitaja oli raamatilainen Siimei. Viinitarhoista koottujen viinivarastojen hoitaja oli sifmiläinen Sabdi.',
        28: 'Öljypuiden ja Alankomaassa kasvavien metsäviikunapuiden hoitaja oli gaderilainen Baal-Haanan. Öljyvarastojen hoitaja oli Jooas.',
        29: 'Saaronissa laitumella käyvien nautojen kaitsija oli saaronilainen Sitrai, ja tasangoilla laitumella käyvien nautojen kaitsija Saafat, Adlain poika.',
        30: 'Kamelien kaitsija oli ismaelilainen Oobil, aasintammojen meeronotilainen Jehdeja.',
        31: 'Lampaiden ja vuohien kaitsija oli hagrilainen Jaasis. Nämä kaikki olivat kuningas Daavidin omaisuuden ylihoitajia.',
        32: 'Joonatan, Daavidin setä, joka oli ymmärtäväinen mies ja kirjanoppinut, oli neuvonantaja. Jehiel, Hakmonin poika, oli kuninkaan lasten luona.',
        33: 'Ahitofel oli kuninkaan neuvonantaja, ja arkilainen Huusai oli kuninkaan ystävä.',
        34: 'Ahitofelin jälkeen tulivat Joojada, Benajan poika, ja Ebjatar. Kuninkaan sotapäällikkö oli Jooab.',
    },
    28: {
        1: 'Daavid kokosi Jerusalemiin kaikki Israelin päämiehet, sukukuntien päämiehet, osastojen päälliköt, jotka palvelivat kuningasta, tuhannen- ja sadanpäämiehet, kuninkaan ja hänen poikiensa kaiken omaisuuden ja karjan ylihoitajat, hovimiehet, sankarit ja kaikki valiosotilaat.',
        2: 'Kuningas Daavid nousi seisomaan jaloilleen ja sanoi: "Kuulkaa minua, veljeni ja kansani. Minä olin aikonut rakentaa huoneen Herran liitonarkin leposijaksi ja Jumalamme jalkojen astinlaudaksi ja olin valmistautunut rakentamaan.',
        3: "Mutta Jumala sanoi minulle: 'Älä sinä rakenna temppeliä nimelleni, sillä sinä olet sotilas ja olet vuodattanut verta.'",
        4: 'Kuitenkin valitsi Herra, Israelin Jumala, minut kaikesta isäni suvusta olemaan Israelin kuninkaana ikuisesti. Sillä Juudan hän valitsi ruhtinaaksi ja Juudan heimosta isäni suvun, ja isäni poikien joukossa olin otollinen hänelle, niin että hän teki minut koko Israelin kuninkaaksi.',
        5: 'Kaikkien poikieni joukosta, sillä Herra on antanut minulle monta poikaa, hän valitsi poikani Salomon istumaan Herran valtakunnan valtaistuimella ja hallitsemaan Israelia.',
        6: "Hän sanoi minulle: 'Sinun poikasi Salomo on rakentava temppelini ja esikartanoni, sillä olen valinnut hänet pojakseni ja minä olen oleva hänelle Isänä.",
        7: "Vahvistan hänen kuninkuutensa iankaikkisesti, jos hän on luja ja pitää käskyni ja oikeuteni, niin kuin hän nyt tekee.'",
        8: 'Nyt sanon koko Israelin, Herran seurakunnan, edessä ja Jumalamme kuullen: Noudattakaa ja tutkikaa kaikkia Herran, Jumalanne, käskyjä, että saisitte pitää omananne tämän hyvän maan ja jättäisitte sen perinnöksi lapsillenne jälkeenne ikiajoiksi.',
        9: 'Sinä, poikani Salomo, opi tuntemaan isäsi Jumala ja palvele häntä ehyellä sydämellä ja alttiilla mielellä, sillä Herra tutkii kaikki sydämet ja ymmärtää kaikki ajatukset ja aivoitukset. Jos häntä etsit, löydät hänet, mutta jos luovut hänestä, hän hylkää sinut iankaikkisesti.',
        10: 'Katso nyt eteesi, sillä Herra on valinnut sinut rakentamaan temppelipyhäkön. Ole luja ja ryhdy työhön."',
        11: 'Sen jälkeen Daavid antoi pojalleen Salomolle temppelin eteisen, sen rakennusten, varastohuoneiden, yläsalien, sisähuoneiden ja armoistuimen huoneen mallin',
        12: 'sekä määräykset kaikesta, mitä hänellä oli mielessään: Herran temppelin esikartanoista ja kaikista kammioista [temppelin] ympärillä, Jumalan temppelin ja pyhien lahjojen aarrekammioista,',
        13: 'sekä myös pappien ja leeviläisten osastoista, kaikesta Herran temppelissä toimitettavasta palveluksesta ja kaikista Herran temppelin palveluksessa tarvittavista esineistä: kullasta,',
        14: 'jokaisen palveluksessa tarvittavan kultaesineen painosta, kaikista hopeakaluista, jokaisen palveluksessa tarvittavan hopeaesineen painosta;',
        15: 'kullasta tehtävien lampunjalkojen ja niiden kunkin lampun kullan painosta, jokaisen lampunjalan ja sen lamppujen painosta; samoin hopeasta tehtävien lampunjalkojen painosta, jokaisen lampunjalan ja sen lamppujen painosta, jokaisen lampunjalan käytön mukaan;',
        16: 'edelleen näkyleipäpöytien kullan painosta, kunkin pöydän erikseen, samoin hopeasta tehtävien pöytien hopeasta;',
        17: 'haarukoiden, maljojen ja kannujen puhtaasta kullasta, samoin kultapikareista, kunkin pikarin painosta, ja hopeapikareista, kunkin pikarin painosta;',
        18: 'myös suitsutusalttarin puhdistetun kullan painosta ja vaunujen mallista, kultakerubeista, joitten tuli levittää siipensä ja peittää Herran liitonarkki.',
        19: '"Tämä kaikki on kirjoituksessa, joka on lähtenyt Herran kädestä. Hän on opettanut minulle kaikki tämän mallin mukaan tehtävät työt."',
        20: 'Daavid sanoi pojalleen Salomolle: "Ole luja ja rohkea ja ryhdy työhön, älä pelkää äläkä arkaile, sillä Herra Jumala, Jumalani, on oleva kanssasi. Hän ei jätä sinua eikä hylkää sinua, kunnes olet saanut valmiiksi kaikki Herran temppelissä tehtävät työt.',
        21: 'Katso, pappien ja leeviläisten osastot ovat valmiit kaikkeen palvelukseen Jumalan temppelissä, ja sinulla on kaikkiin töihin käytettävinäsi niitä, jotka alttiisti ja taitavasti tekevät kaikkea palvelusta, niin myös päämiehet ja koko kansa kaikkiin tehtäviisi."',
    },
    29: {
        1: 'Kuningas Daavid sanoi koko seurakunnalle: "Poikani Salomo, ainoa Jumalan valittu, on nuori ja hento, ja työ on suuri, sillä tämä linna ei ole aiottu ihmiselle, vaan Herralle Jumalalle.',
        2: 'Kaikin voimin olen hankkinut Jumalani temppeliä varten kultaa kultaesineisiin, hopeaa hopeaesineisiin, vaskea vaskiesineisiin, rautaa rautaesineisiin ja puuta puuesineisiin, onykskiviä ja muita jalokiviä, mustankiiltävää ja kirjavaa kiveä, kaikenlaisia kalliita kiviä ja marmorikiveä suuret määrät.',
        3: 'Koska Jumalani temppeli on minulle rakas, luovutan omistamani kullan ja hopean Jumalani temppeliä varten, kaiken sen lisäksi, minkä olen pyhäkköä varten hankkinut:',
        4: 'kolmetuhatta talenttia kultaa, Oofirin kultaa, ja seitsemäntuhatta talenttia puhdistettua hopeaa huoneitten seinien silaamiseksi,',
        5: 'kultaa kultaesineisiin ja hopeaa hopeaesineisiin ja kaikkiin taitajien kätten töihin. Tahtooko kukaan muu tänä päivänä tuoda vapaaehtoisesti täysin käsin lahjoja Herralle?"',
        6: 'Silloin tulivat vapaaehtoisesti perhekuntien päämiehet, Israelin sukukuntien ruhtinaat, tuhannen- ja sadanpäämiehet ja kuninkaan töiden ylivalvojat.',
        7: 'He antoivat Jumalan temppelissä tehtäviin töihin viisituhatta talenttia ja kymmenentuhatta dareikkia kultaa, kymmenentuhatta talenttia hopeaa, kahdeksantoista tuhatta talenttia vaskea ja satatuhatta talenttia rautaa.',
        8: 'Jolla oli hallussaan jalokiviä, antoi ne Herran temppelin aarteisiin geersonilaisen Jehielin huostaan.',
        9: 'Kansa iloitsi heidän alttiudestaan, sillä he antoivat ehyellä sydämellä vapaaehtoiset lahjansa Herralle, ja kuningas Daavid oli myös suuresti iloissaan.',
        10: 'Daavid kiitti Herraa koko seurakunnan läsnäollessa. Daavid sanoi: "Ole kiitetty, Herra, isämme Israelin Jumala, iankaikkisesta iankaikkiseen.',
        11: 'Sinun, Herra, on suuruus ja väkevyys ja loisto ja kunnia ja kirkkaus, sillä sinun on kaikki taivaassa ja maan päällä. Sinun, Herra, on valtakunta, ja sinä olet korotettu kaiken pääksi.',
        12: 'Rikkaus ja kunnia tulevat sinulta, sinä hallitset kaikki, ja kädessäsi on voima ja väkevyys. Vallassasi on tehdä mikä tahansa suureksi ja väkeväksi.',
        13: 'Nyt, Jumalamme, me kiitämme sinua ja ylistämme ihanaa nimeäsi.',
        14: 'Sillä mikä olen minä, ja mikä on kansani kyetäksemme antamaan tällaisia vapaaehtoisia lahjoja? Vaan kaikki tulee sinulta, ja omasta kädestäsi olemme sen sinulle antaneet.',
        15: 'Sillä me olemme muukalaisia ja vieraita edessäsi, niin kuin kaikki isämmekin. Kuin varjo ovat päivämme maan päällä eikä ole, mihin toivonsa panna.',
        16: 'Herra, Jumalamme, kaikki tämä runsaus, jonka olemme hankkineet rakentaaksemme temppelin sinulle, sinun pyhälle nimellesi, on kädestäsi, ja sinun on kaikki tyynni.',
        17: 'Tiedän, Jumalani, että sinä tutkit sydämen ja mielistyt vilpittömyyteen. Vilpittömällä sydämellä minä olen antanut kaikki nämä vapaaehtoiset lahjat, ja nyt olen ilolla nähnyt, kuinka sinun täällä oleva kansasi on antanut sinulle vapaaehtoiset lahjansa.',
        18: 'Herra, meidän isiemme Aabrahamin, Iisakin ja Israelin Jumala, säilytä tällaisina ainiaan kansasi sydämen ajatukset ja aivoitukset ja ohjaa heidän sydämensä puoleesi.',
        19: 'Anna pojalleni Salomolle ehyt sydän noudattamaan käskyjäsi, todistuksiasi ja säädöksiäsi, toimittamaan kaikki tämä ja rakentamaan tämä linna, jota varten minä olen tehnyt valmistuksia."',
        20: 'Daavid sanoi kaikelle seurakunnalle: "Kiittäkää Herraa, Jumalaanne." Koko seurakunta kiitti Herraa, isiensä Jumalaa, ja he kumartuivat maahan ja osoittivat kunniaa Herralle ja kuninkaalle.',
        21: 'Seuraavana päivänä he teurastivat teuraita Herralle ja uhrasivat polttouhreja Herralle: tuhat härkää, tuhat pässiä ja tuhat karitsaa ja niihin kuuluvat juomauhrit sekä teurasuhreja suuren joukon koko Israelin puolesta.',
        22: 'He söivät ja joivat Herran edessä sinä päivänä suuresti iloiten ja tekivät toistamiseen Salomon, Daavidin pojan, kuninkaaksi ja voitelivat hänet Herralle ruhtinaaksi, ja Saadokin papiksi.',
        23: 'Salomo istui Herran valtaistuimelle kuninkaaksi isänsä Daavidin sijaan, ja hän menestyi, ja koko Israel totteli häntä.',
        24: 'Samoin kaikki päämiehet, sankarit ja myös kaikki kuningas Daavidin pojat kättä lyöden lupautuivat kuningas Salomon alamaisiksi.',
        25: 'Herra teki Salomon erittäin suureksi koko Israelin silmissä ja antoi hänelle kuninkuuden loiston, jonka kaltaista yhdelläkään kuninkaalla Israelissa ei ollut ollut ennen häntä.',
        26: 'Daavid, Iisain poika, oli hallinnut koko Israelia.',
        27: 'Aika, jonka hän hallitsi Israelia, oli neljäkymmentä vuotta. Hebronissa hän hallitsi seitsemän vuotta, ja Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.',
        28: 'Hän kuoli päästyään korkeaan ikään, elämästä, rikkaudesta ja kunniasta kylliksi saaneena, ja hänen poikansa Salomo tuli kuninkaaksi hänen jälkeensä.',
        29: 'Daavidin vaiheet, sekä aikaisemmat että myöhemmät, ovat kirjoitettuina näkijä Samuelin historiassa, profeetta Naatanin historiassa ja tietäjä Gaadin historiassa;',
        30: 'samoin koko hänen hallituksensa ja hänen tekemänsä urotyöt sekä hänen, Israelin ja kaikkien maitten valtakuntien kohtalot.',
    },
}
